// ===== CAVIGLIA E PIEDE =====

S.push(M(`caviglia-laterale`,{
sub:`Gradi I-III, regole di Ottawa, 6 fasi riabilitative`,
mat:[MCA],
key:[`Meccanismo: flessione plantare forzata + supinazione in carico; coinvolge spesso il PAA (ATFL) e il PC (CFL)`,`Ottawa: anche un solo item positivo → indagini strumentali`,`Palpare sempre base del V metatarso (avulsione da peroneo breve) e testa del perone (frattura di Maisonneuve)`,`Grado II: recupero 3-6 settimane; grado III: oltre 8 settimane`],
inq:[`Una delle patologie muscolo-scheletriche più frequenti negli sportivi`,`4 articolazioni: tibio-tarsica, sottoastragalica, Chopart, Lisfranc; 26 ossa divise in retro-, meso- e avampiede`,`Legamento laterale esterno: peroneo-astragalico anteriore, peroneo-calcaneare, peroneo-astragalico posteriore`,`Legamento mediale: piano profondo (tibio-astragalico anteriore e posteriore) e superficiale (deltoideo a 3 fasci: tibia-navicolare, tibia-collo dell'astragalo, tibia-sustentaculum tali)`,`Archi: interno 15-18 mm (astragalo, navicolare, I cuneiforme, I metatarso; flessore lungo dell'alluce, adduttore dell'alluce, tibiale posteriore) · esterno 3-5 mm (calcagno, cuboide, V metatarso; peronei) · trasversali`,`Diagnosi differenziale: lesione osteocondrale dell'astragalo, tendinopatia peroneale o del tibiale posteriore`],
tab:[{t:`Classificazione clinica (lezione)`,h:[`Grado`,`Lesione`,`Clinica`,`Recupero`],r:[[`I`,`Stiramento senza lesione (di solito PAA)`,`Indolenzimento, impotenza nulla o minima, carico completo, edema assente o minimo`,`Giorni-1/2 settimane`],[`II`,`Lesione parziale di uno o più legamenti (PAA e PC)`,`Edema moderato, ematoma sotto il malleolo peroneale, limitazione funzionale, lieve instabilità, zoppia con dolore in carico`,`3-6 settimane`],[`III`,`Lesione completa (PAA, PC, PAP)`,`Edema importante, dolore elevato e diffuso, impossibile il carico completo`,`>8 settimane`]]},
{t:`Le 6 fasi riabilitative (lezione)`,h:[`Fase`,`Obiettivo`],r:[[`1`,`Proteggere e prevenire ulteriori lesioni`],[`2`,`Ridurre dolore ed edema`],[`3`,`Ristabilire il ROM e la fisiologica lunghezza dei tessuti`],[`4`,`Recuperare controllo neuromuscolare, forza, resistenza e potenza`],[`5`,`Recuperare propriocezione, coordinazione e agilità`],[`6`,`Ristabilire le abilità funzionali`]]}]},
{tst:[[`Palpazione strutturata`,`LPAA e LPC, legamento deltoideo, base del V metatarso, testa del perone.`,`Avulsione da peroneo breve; Maisonneuve (lacerazione della membrana interossea + frattura prossimale del perone).`]],
f:[[`Van Rijn et al. 2008 – decorso clinico della distorsione acuta di caviglia, revisione sistematica`,`van Rijn 2008 clinical course acute ankle sprain systematic review`,`PMID 18374692`],[`Fong et al. 2007 – epidemiologia delle lesioni di caviglia nello sport (Sports Med)`,`Fong 2007 systematic review ankle injury ankle sprain sports`,`PMID 17190537`],[`Gribble et al. 2016 – International Ankle Consortium (BJSM; titolo come nella slide da verificare)`,`Gribble 2016 International Ankle Consortium lateral ankle sprain`,`PMID 27259750`]]}));

S.push(M(`caviglia-sindesmosi`,{sub:`Distorsione "alta" di caviglia`,key:[`Meccanismo tipico: rotazione esterna + dorsiflessione (es. placcaggio sul piede)`,`Tempi più lunghi della distorsione laterale: non applicarne i tempi`,`Palpare la testa del perone: frattura di Maisonneuve`]},{}));
S.push(M(`achille-medio`,{sub:`Tendinopatia del tratto medio (2-6 cm dall'inserzione)`,key:[`Riposo totale non è la strategia: si gestisce il carico mantenendo l'attività tollerata`,`Progressione: isometrico → HSR → pogo e salti → corsa e COD`,`Escludere sempre la rottura (Thompson) e la TVP`]},{}));

S.push(M(`achille-rottura`,{
sub:`Chirurgia vs conservativo, tabella del carico, protocolli funzionali`,
mat:[MCA],
key:[`La maggior parte delle rotture avviene 2-6 cm sopra l'inserzione (zona "watershed" poco vascolarizzata)`,`Chirurgia: lesione cronica >4-6 settimane con retrazione, o acuta in giovani sportivi con gap >2-3 cm; conservativo: monconi a buon contatto (ecografia), controindicazioni, bassa richiesta`,`I protocolli funzionali precoci danno migliori risultati soggettivi senza aumentare le re-rotture (Suchak); con protocolli funzionali il rischio di re-rottura del conservativo si avvicina a quello chirurgico`,`L'equino potrebbe non essere necessario: la tensione statica del tendine riparato è simile a tutti i gradi di flessione plantare (Labib 2007)`],
inq:[`Clinica: "schiocco", dolore improvviso, solco palpabile, Thompson positivo`,`Tecniche: sutura termino-terminale (gap <2 cm, rotture acute), transfer del flessore lungo dell'alluce FHL (croniche con gap >5 cm: linee di forza simili all'Achille, buona resistenza, basso rischio di fallimento), innesti autologhi (plantare gracile, semitendinoso) o allograft (poco usato)`,`Obiettivi (Strom e Casillas): dolore e tumefazione, mobilità salvaguardando il neotendine, rinforzo del soleo-gastrocnemio, forza e coordinazione dell'arto, rientro graduale evitando il re-injury`],
tab:[{t:`Concessione del carico post-chirurgica (lezione)`,h:[`Settimana`,`Carico`,`Supporti`,`Note cliniche`],r:[[`0-2`,`Non carico / protetto (10-15%)`,`Walker boot in equino 20-30°`,`Evitare dorsiflessione; controllare l'edema`],[`2-4`,`Parziale (20-50%)`,`Walker boot con tallonetti`,`Mobilità passiva-assistita; evitare sforzi`],[`4-6`,`Progressivo (75-100%)`,`Walker boot → scarpa rigida`,`Isometrico; rimozione progressiva del tutore`],[`6+`,`Completo`,`Scarpa con supporto, poi normale`,`Esercizi dinamici; pliometria dalla 12ª settimana`]]},
{t:`Fasi: chirurgico vs conservativo (lezione)`,h:[`Fase`,`Chirurgico`,`Conservativo`],r:[[`1`,`0-4 sett.: tutore o gesso in equino 20-30°, NWB (carico da sett. 2), nessuna mobilizzazione`,`0-2 sett.: gesso o tutore in equino 20-30°, NWB secondo ortopedico`],[`2`,`4-8 sett.: sblocco del tutore (carico completo idealmente a 6 sett.), mobilizzazione cauta sotto soglia, isometrie`,`2-6 sett.: carico progressivo con walker, mobilizzazione sotto soglia`],[`3`,`8-12 sett.: mobilità completa, concentrico poi eccentrico, propriocezione`,`6-12 sett.: rimozione del walker, isometrico → concentrico → eccentrico, controllo neuromuscolare`],[`4`,`12-24 sett.: corsa, pliometria, sport-specifico`,`3-6 mesi: attività sportive leggere, test di performance prima del rientro`]]},
{t:`Chirurgico vs conservativo (lezione)`,h:[`Parametro`,`Chirurgico`,`Conservativo`],r:[[`Re-injury`,`Più basso (2-5%)`,`4-12% con immobilizzazione; simile con protocolli funzionali`],[`Tempo di recupero`,`Simile, spesso più rapido`,`Lieve ritardo nel ritorno allo sport`],[`Complicanze`,`Più alte: infezioni, aderenze, lesioni nervose (surale)`,`Minori, possibile rigidità residua`],[`Forza e performance`,`Lievemente superiori (non sempre significativo)`,`Spesso comparabili con buona riabilitazione`],[`Scelta ideale`,`Attivi, sportivi, giovani`,`Anziani, sedentari, comorbilità`]]}]},
{f:[[`Willits et al. 2010 – chirurgia vs conservativo con riabilitazione accelerata (JBJS Am)`,`Willits 2010 operative nonoperative Achilles accelerated functional rehabilitation`,`PMID 21037028`],[`Brumann et al. 2014 – protocollo accelerato evidence-based dopo riparazione (Injury)`,`Brumann 2014 accelerated rehabilitation Achilles tendon repair evidence-based protocol`,`PMID 25059505`],[`Soroceanu et al. 2012 – chirurgia vs non chirurgia, metanalisi (CORR)`,`Soroceanu 2012 surgical versus nonsurgical acute Achilles rupture meta-analysis`,`PMID 23224384`],[`Labib et al. 2007 – tensione del tendine riparato e posizione in equino`,`Labib 2007 Achilles tendon repair tension plantarflexion`,`PMID 17475143`],[`Maffulli e Ajis 2008 – rotture croniche dell'Achille (JBJS Am)`,`Maffulli Ajis 2008 management chronic ruptures Achilles tendon`,`PMID 18519331`]]}));

S.push({id:`piede-fascite`,d:`Caviglia`,t:`Fascite plantare (dolore plantare al tallone)`,nw:1,
sub:`Stretching, rinforzo ad alto carico, ortesi e anca`,
mat:[MCA,`Manuale schede (ChatGPT) – scheda 46`],
key:[`La fascia origina dalla tuberosità mediale del calcagno e si inserisce sulle falangi prossimali; la porzione centrale è la più ampia`,`Molta discordanza in letteratura: presa in carico precoce e combinazione di stretching, rinforzo e ortesi`,`Rinforzare anche gli abduttori d'anca: un medio gluteo debole aumenta la pronazione e il carico sulla fascia`],
inq:[`Patomeccanica: il peso passa da tibia ad astragalo, che scivola in avanti e medialmente sul calcagno; il calcagno si deprime anteriormente e valgizza, l'arco si appiattisce e la fascia va in tensione`,`Dolore al primo passo del mattino e dopo il riposo, alla palpazione del tubercolo mediale`,`Stretching e mobilizzazione di tricipite surale, fascia plantare e ossa del piede (DiGiovanni 2003)`,`Rinforzo della fascia (high-load, Rathleff 2015), della muscolatura intrinseca e degli stabilizzatori d'anca`,`Ortesi plantari per sostenere l'arco longitudinale e scaricare il tallone (Landorf e Keenan 2007)`],
tab:[{t:`Progressione per l'anca (lezione)`,h:[`Fase`,`Esercizi`],r:[[`Acuta`,`Wall press, clamshell, glute bridge bilaterale`],[`Subacuta`,`Monster walk, glute bridge monolaterale, step-down con focus eccentrico, side-star plank`],[`Avanzata`,`Step-down eccentrico con sovraccarico graduale, esercizi dinamici e sport-specifici`]]}],
red:[`Parestesie plantari o notturne (Baxter, tunnel tarsale), dolore osseo da stress del calcagno, rigidità mattutina diffusa (spondiloartrite).`],
yel:[`Lunga durata, sovrappeso, lavoro in piedi prolungato.`],
tst:[[`Palpazione del tubercolo mediale`,`Pressione all'origine della fascia.`,`Dolore tipico.`],[`Windlass test`,`Dorsiflessione passiva dell'alluce in carico.`,`Riproduzione del dolore plantare.`],[`Squeeze del calcagno`,`Compressione medio-laterale.`,`Dolore: sospetta frattura da stress.`],[`WBLT e forza del polpaccio`,`Dorsiflessione in carico, heel raise.`,`Fattori contribuenti.`]],
ex:[[`Stretching del tricipite surale e della fascia`,`m`,`3×30 s · 2-3 volte/die`,`Al muro con ginocchio esteso e flesso; dita in estensione tirate con la mano.`,`Rimbalzare.`,`Più tempo e frequenza.`],[`Heel raise ad alto carico con asciugamano sotto le dita`,`f`,`3×12 → 8 RM · 3 s salita, 2 s pausa, 3 s discesa · a giorni alterni`,`Su gradino, dita in estensione (windlass) per caricare la fascia.`,`Ridurre il ROM.`,`Zaino con carico.`],[`Muscolatura intrinseca (short foot)`,`c`,`3×10 · 5 s`,`Accorciare il piede senza flettere le dita.`,`Arricciare le dita.`,`In monopodalico.`],[`Clamshell, glute bridge, monster walk`,`f`,`3×12-15`,`Progressione dell'anca (tabella).`,`Compensi lombari.`,`Step-down eccentrico con carico.`]],
fasi:[{n:`Acuta`,w:``,o:`Ridurre il dolore e il carico sulla fascia`,k:`Ortesi, stretching, attivazione dell'anca (wall press, clamshell, bridge)`,c:`Dolore al primo passo in calo`,e:[0,2,3]},{n:`Subacuta`,w:``,o:`Rinforzo`,k:`Heel raise high-load, monster walk, bridge monolaterale, step-down eccentrico`,c:`Heel raise tollerati senza peggioramento`,e:[1,2,3]},{n:`Avanzata`,w:``,o:`Ritorno alle attività`,k:`Step-down con sovraccarico, dinamici e sport-specifici`,c:`Corsa e salti senza flare a 24 h`,e:[1,3]}],
ev:[[`Stretching, rinforzo ad alto carico ed educazione`,`Centrale`,`Moderata (DiGiovanni 2003, Rathleff 2015)`],[`Ortesi plantari e taping`,`Supporto`,`Beneficio a breve termine`],[`Infiltrazioni ripetute di corticosteroide`,`Evitare`,`Rischio di rottura della fascia e atrofia del cuscinetto`]],
rts:{intro:`Il criterio è la tolleranza al carico ripetuto (corsa, salti) con risposta stabile il giorno dopo.`,c:[[`Dolore mattutino`,`NRS al primo passo`,`Basso e stabile`,`Indicatore di irritabilità.`],[`Forza`,`Heel raise standardizzato`,`Simile al lato sano`,`Capacità di carico.`],[`Corsa`,`Volume progressivo`,`Senza flare`,`Carico specifico.`],[`Anca`,`Step-down`,`Controllo del valgo`,`Catena cinetica.`]],pre:[],nota:``},
f:[[`DiGiovanni et al. 2003 – stretching specifico della fascia plantare (JBJS Am)`,`DiGiovanni 2003 tissue-specific plantar fascia-stretching exercise`,`PMID 12851352`],[`Rathleff et al. 2015 – rinforzo ad alto carico nella fasciopatia plantare (Scand J Med Sci Sports)`,`Rathleff 2015 high-load strength training plantar fasciitis randomized`,`PMID 25145882`],[`Landorf, Keenan e Herbert 2004 – tipi di ortesi plantari nella fascite plantare (J Am Podiatr Med Assoc)`,`Landorf Keenan 2004 foot orthoses plantar fasciitis`,`PMID 15547121`]]});

S.push({id:`turf-toe`,d:`Caviglia`,t:`Turf toe (lesione della placca plantare della I metatarso-falangea)`,nw:1,
sub:`Alluce in iperestensione forzata in mischia o nel ruck: gradi, protezione dell'avampiede e ritorno alla spinta`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`Meccanismo: iperestensione forzata dell'alluce con l'avampiede caricato e il tallone sollevato, per esempio quando si spinge in mischia o nel ruck e qualcuno cade sul tallone (pratica clinica)`,`Si lesiona il complesso plantare della I metatarso-falangea (placca plantare, sesamoidi, flessore breve dell'alluce): se non riconosciuto porta a spinta più debole, dolore persistente, deformità e artrosi (Najefi 2018)`,`Meno del 2% richiede chirurgia, quasi sempre gradi III con instabilità o lesione ossea (Gupta 2023)`,`Tempo mediano di rientro: circa 6 settimane con il conservativo e circa 15 dopo chirurgia, in 121 lesioni di 12 studi di livello 4 (Vopat 2019); gruppi con gravità diversa`,`Nessun RCT e nessuna linea guida basata sull'evidenza (Seow 2020): classificazione, test e criteri di rientro vengono da opinione esperta e serie di casi`],
inq:[`La placca plantare è la struttura fibrocartilaginea sotto la testa del I metatarso, in cui sono contenuti i due sesamoidi; con il flessore breve e il flessore lungo dell'alluce stabilizza l'articolazione nella spinta (testi di anatomia)`,`È una lesione relativamente rara ma invalidante, descritta soprattutto nel football americano dopo l'introduzione di superfici artificiali più dure (Najefi 2018); l'aumento di attrito tra scarpa e superficie artificiale è indicato come fattore favorente (Clough 2018)`,`Nella casistica NFL di Madi 2022, però, 29 lesioni su 71 sono avvenute su erba naturale e 29 su sintetico: non è una lesione solo dei campi artificiali`,`La diagnosi si basa su meccanismo, esame clinico e imaging: RX in carico con confronto della posizione dei sesamoidi, RM per l'estensione della lesione della placca (Clough 2018; dettagli dalla pratica clinica)`,`I test di stress e di instabilità, come il cassetto verticale, sono considerati decisivi per l'indicazione chirurgica (Clough 2018, opinione esperta: la loro accuratezza non è stata misurata)`,`La rigidità in dorsiflessione è la complicanza più riportata nelle serie pubblicate (Seow 2020, 16 casi)`,`Nessun dato di incidenza specifico per il rugby è stato trovato: la rilevanza per mischia, ruck e spinta è giudizio clinico`],
tab:[{t:`Gradi della lesione (sintesi)`,z:`I`,h:[`Grado`,`Cosa succede`,`Rientro indicativo (Gupta 2023)`],r:[[`I`,`Stiramento della placca plantare, dolore localizzato, poco gonfiore, articolazione stabile`,`Con dolore minimo o assente in carico normale, tradizionalmente dopo 3-5 giorni`],[`II`,`Lesione parziale, gonfiore ed ecchimosi, dorsiflessione dolorosa e limitata`,`Di solito 2-4 settimane perse, spesso con taping al rientro`],[`III`,`Rottura completa della placca, possibile lesione dei sesamoidi o instabilità`,`4-6 settimane o più, secondo il trattamento`],[`Nota`,`Descrizione dei gradi dai testi e dalle revisioni narrative`,`Tempi da una revisione narrativa, non da trial`]]},{t:`Ritorno allo sport nelle serie pubblicate (Vopat 2019)`,z:`R`,h:[`Gruppo`,`Tempo mediano di rientro`],r:[[`Conservativo (58 lesioni)`,`5,85 settimane (da 3,0 a 8,7)`],[`Chirurgia (63 lesioni)`,`14,70 settimane (da 6,0 a 156,4)`],[`Grado II`,`8,70 settimane`],[`Grado III`,`16,50 settimane`],[`Professionisti`,`14,70 settimane`],[`Liceo e college`,`16,50 settimane`],[`Limite`,`Il 46,3% delle lesioni non era classificabile per grado; un solo grado I; studi di livello 4`]]}],
red:[`Sesamoidi migrati verso il tallone alla RX o diastasi di un sesamoide bipartito: rottura completa della placca, invio all'ortopedico del piede.`,`Cassetto verticale con instabilità evidente o alluce deviato dopo il trauma: possibile indicazione chirurgica (Clough 2018).`,`Impossibilità di flettere attivamente l'interfalangea dell'alluce: sospetta lesione del flessore lungo dell'alluce.`,`Frattura dei sesamoidi o della base della falange, o lesione osteocondrale della testa metatarsale.`,`Dolore che non migliora dopo alcune settimane di protezione: lesione cronica non riconosciuta, con esiti peggiori (Najefi 2018).`,`Queste red flag vengono dalla pratica clinica e dalle revisioni narrative, non da studi di accuratezza.`],
yel:[`Sottovalutare la lesione ("è solo l'alluce") e continuare a giocare.`,`Paura di spingere sull'avampiede, con appoggio sul bordo esterno del piede anche dopo la guarigione.`,`Pressione per rientrare con infiltrazioni o antidolorifici prima che la spinta sia recuperata.`],
tst:[[`Palpazione del complesso plantare`,`Pressione sulla placca plantare e su ciascun sesamoide, confronto con il piede sano.`,`Localizza la lesione; dolore sui sesamoidi orienta anche a fratture o sesamoidite.`],[`Dorsiflessione passiva della I metatarso-falangea`,`Goniometro sulla dorsiflessione dell'alluce, a piede scarico e in carico.`,`Dolore e limitazione indicano gravità; è anche la misura per seguire i progressi.`],[`Cassetto verticale (Lachman della metatarso-falangea)`,`Si stabilizza il metatarso e si trasla la falange prossimale in senso dorsale, confronto con il lato sano.`,`Traslazione aumentata o dolore: lesione della placca e possibile instabilità (Clough 2018; accuratezza non misurata).`],[`Flessione attiva e forza dell'alluce`,`Flessione della metatarso-falangea e dell'interfalangea contro resistenza; dinamometro manuale sotto la falange prossimale, confronto tra lati.`,`Valuta flessore breve e lungo; monitoraggio e criterio di rientro.`],[`RX in carico e RM`,`Su indicazione medica; RX bilaterale per confrontare i sesamoidi.`,`Sesamoidi migrati, fratture, estensione della lesione della placca.`],[`Heel raise su una gamba`,`Massime ripetizioni a ritmo costante salendo sull'avampiede, confronto tra lati.`,`Riproduce il carico della spinta: utile per seguire il recupero e come criterio di rientro.`]],
ex:[[`Mobilità della I metatarso-falangea`,`m`,`2-3×10-15, 1-2 volte al giorno (proposta operativa)`,`Flessione e dorsiflessione attive e attivo-assistite dell'alluce entro il dolore; mobilizzazione del terapista quando la fase acuta è passata.`,`Forzare la dorsiflessione nelle prime fasi: è il movimento che ha causato la lesione.`,`Dorsiflessione in carico, in affondo con il tallone sollevato.`],[`Isometrici dei flessori dell'alluce`,`i`,`5×20-30 s · RPE 3-5 · quotidiano (proposta operativa)`,`Seduto, premere l'alluce contro il pavimento o il dinamometro senza staccare il tallone.`,`Dolore oltre 3/10 sulla placca.`,`Raccolta dell'asciugamano, poi in piedi.`],[`Controllo dell'arco e intrinseci (short foot)`,`c`,`3×10 da 5-10 s (proposta operativa)`,`Accorciare il piede avvicinando la testa del I metatarso al tallone, senza flettere le dita.`,`Arricciare le dita invece di sollevare l'arco.`,`In piedi su una gamba, poi in movimento.`],[`Heel raise progressivi`,`f`,`3×12-15 → 4×6-8 con carico · RPE 6-8 · 3/sett. (proposta operativa)`,`Da due piedi a uno solo, poi con carico; salire fino a dove la dorsiflessione dell'alluce è senza dolore, il peso sul I raggio.`,`Scaricare sul bordo esterno del piede per evitare l'alluce.`,`Heel raise con carico pesante e rapidi.`],[`Ritorno alla corsa`,`p`,`3 sedute/sett. a giorni alterni, da intervalli di cammino-corsa a corsa continua (proposta operativa)`,`Con scarpa rigida o soletta rigida e taping che limitano la dorsiflessione; aumentare prima il volume, poi la velocità.`,`Iniziare dagli sprint.`,`Accelerazioni e sprint.`],[`Pliometria, sprint e spinta in mischia`,`p`,`2-3×6-10 contatti o ripetizioni, 2 sedute/sett. (proposta operativa)`,`Saltelli, balzi, cambi di direzione, sprint con partenze dai blocchi; spinta su slitta e sulla macchina da mischia con avampiede caricato.`,`Saltare tappe o lavorare con dolore sulla placca il giorno dopo.`,`Contatto, ruck e mischia piena.`],[`Condizione fisica generale`,`f`,`2-4 sedute/sett. (proposta operativa)`,`Bici con il pedale sotto il mezzo piede o il tallone, piscina, forza dell'arto superiore e del tronco, forza degli arti inferiori senza spinta sull'avampiede.`,`Esercizi in punta di piedi o affondi profondi con l'alluce in dorsiflessione nelle prime settimane.`,`Corsa e lavoro con la squadra.`]],
fasi:[{n:`Protezione`,w:`grado I: pochi giorni; grado II: 1-2 sett.; grado III: secondo l'ortopedico (indicativo)`,o:`Ridurre dolore e gonfiore, proteggere la placca dalla dorsiflessione`,k:`Ghiaccio e scarico relativo; scarpa rigida, soletta rigida o taping che limitano la dorsiflessione; nei gradi III tutore o stampelle secondo l'ortopedico (pratica clinica)`,c:`Cammino senza dolore con la protezione`,e:[1,6]},{n:`Mobilità e carico`,w:`circa 1-4 sett. (indicativo)`,o:`Recuperare la dorsiflessione senza dolore e il carico sul I raggio`,k:`La rigidità in dorsiflessione è la complicanza più riportata (Seow 2020): la mobilità va recuperata gradualmente, non trascurata`,c:`Dorsiflessione in aumento, cammino normale senza protezione`,e:[0,1,2,6]},{n:`Forza`,w:`circa 3-8 sett. (indicativo)`,o:`Forza dei flessori dell'alluce e del polpaccio`,k:`I protocolli conservativi descritti hanno 3 fasi fino a circa 10 settimane; quelli post-chirurgici 4 fasi fino a circa 20 settimane (Gupta 2023)`,c:`Heel raise su una gamba senza dolore, forza dell'alluce vicina al lato sano`,e:[0,2,3]},{n:`Corsa, potenza e contatto`,w:`conservativo: mediana circa 6 sett.; chirurgia: mediana circa 15 sett. (Vopat 2019)`,o:`Sprint, cambi di direzione, spinta in mischia`,k:`Taping o soletta rigida al rientro, soprattutto nei gradi II (Gupta 2023)`,c:`Criteri del capitolo del rientro`,e:[3,4,5]}],
ev:[[`Trattamento conservativo graduato per gravità (protezione, recupero della mobilità, rinforzo, rientro progressivo)`,`Centrale`,`Revisioni narrative (Gupta 2023, Najefi 2018) e serie di casi; meno del 2% va in chirurgia; nessun RCT`],[`Chirurgia nei gradi III con instabilità, sesamoidi migrati o lesione ossea`,`Supporto`,`Serie di casi (Seow 2020: 8 studi, 16 casi, qualità scarsa); rientro più lento (mediana 14,7 settimane, Vopat 2019)`],[`Taping o soletta rigida che limitano la dorsiflessione al rientro`,`Supporto`,`Raccomandati nelle revisioni narrative (Gupta 2023); efficacia non studiata`],[`Riconoscimento e trattamento precoci`,`Centrale`,`Opinione esperta concorde (Najefi 2018, Clough 2018): le lesioni croniche hanno esiti peggiori`],[`Tornare in campo con dolore alla dorsiflessione o alla spinta`,`Evitare`,`Rischio di lesione cronica con spinta debole, deformità e degenerazione articolare (Najefi 2018)`],[`Forzare la dorsiflessione nelle prime fasi`,`Evitare`,`Proposta operativa: è il meccanismo della lesione; va recuperata gradualmente`]],
rts:{intro:`Non esistono criteri di rientro validati: le revisioni descrivono tempi indicativi per grado (Gupta 2023) e le serie riportano tempi mediani (Vopat 2019). Per gli atleti con lesioni di basso grado si prevede il ritorno al livello precedente; con lesioni di grado più alto circa il 70% mantiene il livello di prestazione (Gupta 2023). Nei giocatori NFL la prestazione dopo la lesione non era diversa da prima (Madi 2022). Le soglie qui sotto sono proposte operative.`,c:[[`Dolore`,`Palpazione della placca e dei sesamoidi; dolore in allenamento e il giorno dopo`,`Dolore minimo o assente nel carico normale e il giorno dopo (proposta operativa)`,`Per il grado I è il criterio indicato nelle revisioni (Gupta 2023).`],[`Dorsiflessione dell'alluce`,`Goniometro in carico, confronto con il lato sano`,`Senza dolore nell'arco che serve per sprintare; differenza piccola con il lato sano (proposta operativa)`,`La spinta nello sprint e in mischia richiede dorsiflessione dell'alluce sotto carico.`],[`Forza dei flessori dell'alluce`,`Dinamometro manuale sotto la falange prossimale, lettura in kg, confronto tra lati`,`LSI ≥90% (proposta operativa)`,`La spinta debole è l'esito tipico delle lesioni non recuperate (Najefi 2018).`],[`Heel raise su una gamba`,`Massime ripetizioni a ritmo costante, confronto tra lati`,`LSI ≥90%, con il peso sul I raggio (proposta operativa)`,`Riproduce il carico ripetuto sull'avampiede della corsa.`],[`Salti e sprint`,`Hop test su una gamba, sprint di 20-40 m, cambi di direzione`,`Senza dolore né compensi, tempi vicini ai valori precedenti (proposta operativa)`,`Sono i gesti in cui l'alluce lavora di più in dorsiflessione.`],[`Spinta in mischia e nel ruck`,`Macchina da mischia, slitta, poi ruck con contatto`,`Spinta piena sull'avampiede senza dolore (proposta operativa)`,`È il gesto rugbistico tipico della lesione.`],[`Protezione`,`Taping o soletta rigida in allenamento e partita`,`Per le prime settimane dopo il rientro, soprattutto nei gradi II (proposta operativa sulla base di Gupta 2023)`,`Limita la dorsiflessione forzata mentre la placca matura.`]],pre:[`Nei gradi III e dopo chirurgia i tempi li decide l'ortopedico; i protocolli post-chirurgici arrivano a circa 20 settimane (Gupta 2023)`,`Primo contatto e prima mischia in allenamento, non in partita (proposta operativa)`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`I dati sul rientro vengono soprattutto dal football americano; per il rugby non sono stati trovati studi. Nella metanalisi di Vopat i tempi per grado sono poco affidabili (un solo grado I, quasi metà delle lesioni non classificabili).`},
sez:[{h:`Prevenzione`,b:[`Non sono stati trovati studi sulla prevenzione del turf toe (lacuna)`,`L'attrito elevato tra scarpa e superficie artificiale è indicato come fattore favorente (Clough 2018), ma nella casistica NFL le lesioni erano divise quasi a metà tra erba e sintetico (Madi 2022)`,`Scarpe con suola non troppo flessibile nell'avampiede o solette rigide nei giocatori con precedenti lesioni (proposta operativa, senza studi)`,`Mantenere in stagione la forza dei flessori dell'alluce e del polpaccio (proposta operativa)`,`Programmi di riscaldamento come Activate riducono gli infortuni nel rugby giovanile (Hislop 2017), senza dati specifici sull'alluce`]}],
f:[[`Vopat et al. 2019 – ritorno allo sport dopo turf toe, revisione sistematica e metanalisi (Orthop J Sports Med)`,`Vopat 2019 return to sport turf toe systematic review meta-analysis`,`PMID 31663005`],[`Seow et al. 2020 – opzioni di trattamento del turf toe, revisione sistematica (J Foot Ankle Surg)`,`Seow 2020 treatment options turf toe systematic review`,`PMID 31882133`],[`Gupta et al. 2023 – turf toe nell'atleta: trattamento, protocolli riabilitativi e rientro, revisione narrativa (Curr Rev Musculoskelet Med)`,`Gupta 2023 turf toe injuries athlete treatment rehabilitation protocols return to play`,`PMID 37789169`],[`Najefi et al. 2018 – turf toe, aggiornamento clinico (EFORT Open Rev)`,`Najefi 2018 turf toe clinical update`,`PMID 30305934`],[`Clough e Majeed 2018 – turf toe, concetti attuali e revisione della letteratura (Foot Ankle Clin)`,`Clough Majeed 2018 turf toe injury current concepts review`,`PMID 30414661`],[`Madi et al. 2022 – esiti del turf toe nei giocatori NFL (J Foot Ankle Surg)`,`Madi 2022 outcome turf toe injuries NFL players`,`PMID 35697653`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`],[`Hislop et al. 2017 – programma di controllo del movimento nel rugby scolastico, RCT a cluster (BJSM)`,`Hislop 2017 movement control exercise programme schoolboy rugby`,`PMID 28515056`]]});

S.push({id:`fratture-malleolari-orif`,d:`Caviglia`,t:`Fratture malleolari dopo ORIF`,nw:1,
sub:`Placca e viti sul malleolo: carico precoce, ferita, forza e ritorno al campo`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`Meccanismo tipico nel rugby: piede bloccato a terra mentre il corpo ruota, oppure un giocatore che cade sulla gamba nel placcaggio o nel ruck (pratica clinica, nessuno studio sul rugby)`,`Con una fissazione stabile il carico precoce (entro 2-3 settimane) è sicuro: probabilmente non aumenta reinterventi né complicanze (Lewis 2024, Cochrane; Sernandez 2021); il vantaggio sulla funzione è reale nelle prime settimane ma piccolo (Lewis 2024, Chen 2024)`,`RCT di Dehghan 2016 (110 operati): carico e mobilità a 2 settimane invece di gesso e scarico per 6 settimane danno a 6 settimane più ROM e una funzione migliore, senza più problemi di ferita`,`Non muovere attivamente la caviglia prima che la ferita sia guarita: più complicanze della ferita (OR 3,11) e nessun vantaggio a lungo termine (Sernandez 2021)`,`Negli atleti operati il rientro allo sport è dell'87,1%, in media dopo circa 134 giorni (4,5 mesi), di più nelle bi e trimalleolari (Mazzella 2025); nessun dato sul rugby`,`Negli studi il rientro si decide quasi sempre con il tempo trascorso dall'intervento, non con test oggettivi (Wright 2023): qui i criteri sono proposte operative`],
inq:[`Classificazione di uso clinico (dai testi): mono, bi o trimalleolare; per il perone Weber A (sotto la sindesmosi), B (all'altezza) e C (sopra, con sindesmosi quasi sempre coinvolta). L'ORIF si fa quando la frattura è instabile o spostata`,`Nelle Weber C e in parte delle B si fissa anche la sindesmosi con viti o sistemi a bottone: lo scarico può essere più lungo e decide il chirurgo (pratica clinica). Per la sindesmosi vedi la scheda dedicata`,`Che cosa vuol dire precoce cambia tra gli studi: carico entro 3 settimane nella Cochrane (Lewis 2024), carico e mobilità a 2 settimane nell'RCT di Dehghan 2016, carico nelle prime 6 settimane nella metanalisi di Chen 2024`,`Dopo l'intervento un tutore rimovibile, invece di un gesso, può migliorare la funzione (certezza bassa) e probabilmente la qualità di vita (certezza moderata), senza più reinterventi (Lewis 2024). Nel trattamento conservativo non c'è differenza tra tutore rimovibile e gesso`,`Per gli interventi fisioterapici specifici (stretching aggiuntivo, mobilizzazioni, esercizi neuromuscolari, tapis roulant antigravitario) la Cochrane non riesce a dire se siano migliori delle cure abituali: certezza molto bassa (Lewis 2024). Nel giovane atleta la progressione di forza, corsa e contatto resta comunque necessaria per rientrare (proposta operativa)`,`Nell'RCT di Dehghan 2016 il gruppo con gesso e scarico ha avuto più rimozioni dei mezzi di sintesi per irritazione della placca (19% vs 2%)`,`Negli anziani oltre i 60 anni il gesso a contatto stretto ha dato a 6 mesi una funzione equivalente alla chirurgia, con meno infezioni (1% vs 10%) ma più malunioni radiologiche (15% vs 3%) (Willett 2016): dato utile per capire i rischi della chirurgia, non trasferibile al giovane rugbista`],
tab:[{t:`Carico e mobilità precoci dopo ORIF: cosa dicono gli studi`,z:`T`,h:[`Fonte e disegno`,`Confronto`,`Risultato`],r:[[`Lewis 2024, Cochrane (12 studi, 1403 adulti)`,`Carico entro 3 settimane vs carico ritardato`,`Funzione probabilmente migliore (3,56 punti), differenza non clinicamente rilevante; reinterventi simili (certezza bassa)`],[`Lewis 2024, Cochrane (6 studi, 677 operati)`,`Tutore rimovibile vs gesso`,`Funzione forse migliore (6,39 punti, certezza bassa); qualità di vita probabilmente migliore`],[`Chen 2024 (11 RCT, 862 pazienti)`,`Carico precoce vs tardivo`,`Funzione migliore a 6, 12 e 24-26 settimane; ritorno anticipato alle attività; complicanze non aumentate in modo significativo; l'effetto dipende anche dagli esercizi di mobilità`],[`Dehghan 2016 (RCT, 110 pazienti)`,`Carico e ROM a 2 settimane vs gesso e scarico per 6 settimane`,`A 6 settimane ROM 41 vs 29, Olerud-Molander 45 vs 32; ritorno al lavoro uguale; nessuna differenza di ferita, infezioni o perdita di riduzione`],[`Sernandez 2021 (20 studi di livello I, 1130 casi)`,`Carico e ROM precoci vs ritardati`,`Carico precoce con fissazione stabile: esiti e complicanze simili. ROM attivo prima della guarigione della ferita: più complicanze della ferita (OR 3,11), infezioni non aumentate`]]},{t:`Ritorno allo sport negli atleti operati (Mazzella 2025)`,z:`R`,h:[`Dato`,`Valore`],r:[[`Studi e atleti`,`17 studi, 1422 atleti, età media 31,4 anni`],[`Trattati con ORIF`,`89,4%`],[`Ritorno allo sport`,`87,1%`],[`Tempo medio al rientro`,`134,5 giorni, circa 4,5 mesi`],[`Bi e trimalleolari`,`Tempi più lunghi, fino a 720 giorni`],[`FAOS sport a 12 mesi`,`85,6 in media`],[`Limite`,`Studi di qualità limitata e non standardizzati; nessuno sul rugby`]]}],
red:[`Ferita arrossata, calda, che secerne o si riapre, febbre: sospetta infezione o deiscenza, invio al chirurgo. Negli anziani operati infezioni e problemi di ferita hanno riguardato il 10% dei casi (Willett 2016).`,`Polpaccio dolente, gonfio e caldo, oppure fiato corto e dolore toracico: sospetta trombosi venosa profonda o embolia polmonare, invio urgente.`,`Dolore sproporzionato, pelle tesa, formicolii o piede freddo nei primi giorni: problema neurovascolare o sindrome compartimentale, invio urgente.`,`Dolore che aumenta con il carico invece di calare, nuova deformità o scatto: possibile perdita della riduzione o cedimento della sintesi, controllo RX.`,`Dolore sproporzionato e persistente con alterazioni di colore, temperatura e sudorazione del piede: sospetta sindrome dolorosa regionale complessa.`,`Queste red flag vengono dalla pratica clinica; le fonti della scheda riportano solo le complicanze di ferita e infezione.`],
yel:[`Paura di caricare il piede operato o di rompere la placca.`,`Paura del cambio di direzione e del contatto sul piede operato.`,`Pressione per rientrare a stagione in corso.`,`Rigidità e gonfiore vissuti come definitivi.`],
tst:[[`Ferita ed edema`,`Ispezione della ferita; circonferenza a otto della caviglia con metro a nastro, confronto con il lato sano.`,`Ferita guarita prima della mobilità attiva (Sernandez 2021); l'edema del giorno dopo dice come la caviglia ha tollerato il carico (pratica clinica).`],[`Olerud-Molander Ankle Score (OMAS)`,`Questionario da 0 a 100, ripetuto nel tempo.`,`È l'esito principale di molti studi (Dehghan 2016, Willett 2016): utile per seguire i progressi e confrontarsi con i dati.`],[`Dorsiflessione in carico (knee to wall)`,`Affondo verso il muro con il tallone a terra; distanza alluce-muro in cm o inclinometro sulla tibia; confronto tra lati.`,`Dopo l'immobilizzazione la dorsiflessione è spesso il deficit più evidente (pratica clinica). Soglia nel capitolo del rientro.`],[`Calf raise monopodalico fino a esaurimento`,`In piedi su un gradino, una gamba, ritmo regolare (metronomo), salita completa; ripetizioni fino a perdere l'altezza.`,`Forza resistente dei flessori plantari; LSI per il rientro.`],[`Forza con dinamometro manuale`,`Dorsiflessione, inversione ed eversione in kg, confronto tra lati.`,`Monitoraggio e criteri di rientro. La flessione plantare è troppo forte per il dinamometro manuale: meglio il calf raise.`],[`Hop test e Y balance`,`Hop singolo, triplo e laterale; Y balance in appoggio monopodalico.`,`Solo nelle fasi finali, a consolidazione avvenuta; LSI per il rientro (soglie proposte operative).`]],
ex:[[`Mobilità attiva di caviglia e piede`,`m`,`3×15 · 3-4 volte al giorno (proposta operativa)`,`Solo a ferita guarita: flesso-estensione, circonduzione, inversione ed eversione, alfabeto con l'alluce; dita del piede e ginocchio anche prima.`,`Iniziare il movimento attivo della caviglia con la ferita ancora aperta (Sernandez 2021).`,`Mobilità in carico e affondo al muro.`],[`Carico progressivo e rieducazione del cammino`,`c`,`Cammino quotidiano crescente, carico secondo il chirurgo (proposta operativa)`,`Con tutore rimovibile e stampelle, poi una stampella, poi senza; passo simmetrico, rullata completa dal tallone alle dita.`,`Zoppia mantenuta per settimane, passo corto sul lato operato.`,`Senza tutore, scale, terreni irregolari, cammino veloce.`],[`Affondo al muro per la dorsiflessione`,`m`,`3×10-15 con 3-5 s in fondo · quotidiano (proposta operativa)`,`Tallone a terra, ginocchio che avanza sopra il secondo dito.`,`Tallone che si alza o piede che collassa in pronazione.`,`Con carico (manubrio sul ginocchio) o con elastico che spinge indietro l'astragalo.`],[`Calf raise progressivo`,`f`,`3×15 → 4×6-10 · RPE 7-8 · 3/sett. (proposta operativa)`,`Bipodalico, poi monopodalico, a ginocchio teso e flesso (soleo).`,`ROM parziale, oscillare con il corpo.`,`Con carico, poi rapidi e saltellati.`],[`Equilibrio e controllo monopodalico`,`c`,`3-5×30-45 s · quotidiano (proposta operativa)`,`Su una gamba, ginocchio morbido, piede stabile.`,`Piede che si appoggia sul bordo esterno, anca che cede.`,`Occhi chiusi, superficie instabile, passaggi della palla, spinte del partner.`],[`Forza globale e condizione fisica`,`f`,`4×5-8 · RPE 7-9 · 2-3/sett.; bici o ergometro 2-4/sett. (proposta operativa)`,`All'inizio senza carico sul lato operato: parte alta, tronco, arto sano, ergometro a braccia. Poi bici, squat, stacco rumeno, affondi, step-up.`,`Fermarsi del tutto per settimane: il ricondizionamento finale si allunga.`,`Bilanciere sulle spalle, esercizi unilaterali, sprint in bici.`],[`Saltelli, corsa e cambi di direzione`,`p`,`2-3 sedute/sett. a giorni alterni, guidate da dolore ed edema (proposta operativa)`,`Saltelli bipodali, poi monopodali; corsa progressiva; hop in avanti e laterali; cambi di direzione; infine contatto, ruck e mischia.`,`Aumentare volume e intensità insieme; correre se il giorno dopo la caviglia è più gonfia.`,`Sprint, cambi di direzione reattivi, placcaggio e mischia.`]],
fasi:[{n:`Protezione e ferita`,w:`0-2 sett. (indicativo; decide il chirurgo)`,o:`Guarigione della ferita, controllo dell'edema, mantenere la condizione fisica`,k:`Elevazione dell'arto; dita e ginocchio liberi; niente movimento attivo della caviglia prima della guarigione della ferita (Sernandez 2021); allenamento di parte alta, tronco e arto sano`,c:`Ferita guarita, punti rimossi, via libera al carico`,e:[5]},{n:`Carico e mobilità`,w:`circa 2-6 sett. (indicativo)`,o:`Carico progressivo, ROM, cammino senza stampelle`,k:`Con fissazione stabile negli RCT carico e mobilità partivano a 2 settimane (Dehghan 2016); tutore rimovibile al posto del gesso (Lewis 2024). Con fissazione della sindesmosi o sintesi fragile lo scarico può durare di più (pratica clinica)`,c:`Cammino senza stampelle e senza zoppia, edema stabile (proposta operativa)`,e:[0,1,2,5]},{n:`Forza e controllo`,w:`circa 6-12 sett. (indicativo)`,o:`Dorsiflessione simmetrica, forza del polpaccio, equilibrio monopodalico`,k:`Carichi progressivi; bici e forza generale`,c:`Calf raise monopodalico con LSI almeno 80%, dorsiflessione in carico vicina al lato sano, equilibrio monopodalico stabile (proposta operativa)`,e:[2,3,4,5]},{n:`Corsa e potenza`,w:`circa 3-4 mesi (indicativo)`,o:`Tollerare impatti, corsa e cambi di direzione`,k:`Prima saltelli bipodali, poi corsa lineare, poi hop monopodali e cambi di direzione`,c:`Corsa e hop senza dolore né aumento di edema il giorno dopo (proposta operativa)`,e:[3,4,5,6]},{n:`Ritorno al rugby`,w:`in media dopo circa 4,5 mesi negli studi; di più nelle bi e trimalleolari (Mazzella 2025)`,o:`Allenamento completo con contatto`,k:`Contatto progressivo, mischia, ruck, sprint`,c:`Criteri del capitolo del rientro`,e:[5,6]}],
ev:[[`Carico precoce (entro 2-3 settimane) dopo fissazione stabile`,`Centrale`,`Cochrane (Lewis 2024) e metanalisi di RCT (Chen 2024, Sernandez 2021): sicuro e con vantaggi precoci, ma la differenza di funzione è piccola e non sempre clinicamente rilevante`],[`Tutore rimovibile invece del gesso dopo l'intervento`,`Supporto`,`Lewis 2024: funzione forse migliore (certezza bassa), qualità di vita probabilmente migliore (certezza moderata), reinterventi simili`],[`Esercizi di mobilità associati al carico, a ferita guarita`,`Supporto`,`Chen 2024: l'effetto del carico precoce varia con gli esercizi di ROM; Sernandez 2021: nessun vantaggio a lungo termine del ROM molto precoce`],[`Programmi fisioterapici specifici aggiuntivi (stretching, mobilizzazioni, esercizi neuromuscolari)`,`Supporto`,`Lewis 2024: efficacia incerta, certezza molto bassa. Nell'atleta la progressione di forza e corsa resta una proposta operativa necessaria per il rientro`],[`Mobilità attiva della caviglia prima della guarigione della ferita`,`Evitare`,`Sernandez 2021: più complicanze della ferita (OR 3,11) senza vantaggi a lungo termine`],[`Rientro al rugby deciso solo dal tempo trascorso`,`Evitare`,`Wright 2023: è la pratica più diffusa negli studi, ma non si basa su criteri validati`]],
rts:{intro:`Negli atleti operati il rientro allo sport è dell'87,1%, in media dopo circa 134 giorni (Mazzella 2025), ma negli studi il criterio è quasi sempre il tempo trascorso dall'intervento (Wright 2023). Non esistono criteri validati né dati sul rugby: le soglie qui sotto sono proposte operative, prese in prestito da altre condizioni di caviglia.`,c:[[`Consolidazione e via libera del chirurgo`,`Controllo RX e visita ortopedica`,`Frattura consolidata, mezzi di sintesi senza problemi; con fissazione della sindesmosi decide il chirurgo`,`Il contatto e i cambi di direzione caricano la caviglia in rotazione, cioè nella direzione del trauma.`],[`Dolore ed edema`,`Dolore durante l'allenamento (scala 0-10) e circonferenza a otto la mattina dopo`,`Dolore al massimo 2/10 senza peggiorare il giorno dopo; edema stabile (proposta operativa)`,`Dolore ed edema che crescono dopo il carico indicano che la caviglia non tollera ancora quel volume.`],[`Dorsiflessione in carico`,`Knee to wall, distanza alluce-muro in cm`,`Differenza con il lato sano entro 2 cm (proposta operativa)`,`Serve per la posizione bassa in mischia e nel ruck, per accelerare e per l'affondo nel placcaggio.`],[`Forza del polpaccio`,`Calf raise monopodalico fino a esaurimento`,`LSI almeno 90% (proposta operativa)`,`Il polpaccio assorbe e restituisce il carico in corsa, salto e spinta in mischia.`],[`Forza di inversione ed eversione`,`Dinamometro manuale in kg, confronto tra lati`,`LSI almeno 90% (proposta operativa)`,`Gli eversori controllano la caviglia nei cambi di direzione e negli appoggi instabili (pratica clinica).`],[`Hop test e cambi di direzione`,`Hop singolo, triplo e laterale; percorso con cambi di direzione`,`LSI almeno 90%, senza dolore né esitazione (proposta operativa)`,`Riproducono gli appoggi monopodali veloci del rugby.`],[`Contatto e gesti del rugby`,`Progressione: corsa con la squadra, contatto con scudo, placcaggio controllato, ruck e mischia, contatto pieno`,`Tutta la progressione senza sintomi (proposta operativa)`,`Nel rugby il contatto è il test finale.`]],pre:[`Decisione condivisa con il chirurgo e con lo staff`,`Bi e trimalleolari: tempi più lunghi e più prudenza (Mazzella 2025)`,`Chiedere all'atleta se si sente pronto a cambiare direzione e a spingere in mischia sul piede operato: la paura modifica gli appoggi`,`Primo contatto pieno in allenamento, non in partita (proposta operativa)`,`Rimozione dei mezzi di sintesi: tempi e rientro dopo la rimozione non sono definiti nelle fonti della scheda, decide il chirurgo`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`Non sono stati trovati studi sul rugby. Mazzella 2025 riunisce sport diversi con studi di qualità limitata; l'uso di tutori o taping nelle prime partite non è studiato nelle fonti della scheda (lacuna).`},
sez:[{h:`Prevenzione`,b:[`Non sono stati trovati studi sulla prevenzione delle fratture di caviglia nel rugby (lacuna)`,`Programmi di riscaldamento come Activate riducono gli infortuni nel rugby giovanile (Hislop 2017), senza dati specifici sulle fratture di caviglia`,`Dopo il rientro mantenere in stagione calf raise, lavoro di eversori ed equilibrio monopodalico (proposta operativa)`,`Misurare a inizio stagione dorsiflessione in carico, calf raise e forza di inversione ed eversione con il dinamometro, per avere valori di riferimento in caso di infortunio (proposta operativa)`,`Per la distorsione laterale e la sindesmosi vedi le schede dedicate`]}],
f:[[`Lewis et al. 2024 – riabilitazione dopo frattura di caviglia nell'adulto, revisione Cochrane`,`Lewis 2024 Cochrane rehabilitation for ankle fractures in adults`,`PMID 39312389`],[`Chen et al. 2024 – carico precoce vs tardivo dopo chirurgia per frattura di caviglia, metanalisi di RCT (J Foot Ankle Res)`,`Chen 2024 early weight-bearing later weight-bearing ankle fracture surgery meta-analysis`,`PMID 38635458`],[`Dehghan et al. 2016 – carico e mobilità precoci vs scarico e gesso dopo ORIF di fratture instabili di caviglia, RCT (J Orthop Trauma)`,`Dehghan 2016 early weightbearing range of motion open reduction internal fixation unstable ankle fractures randomized`,`PMID 27045369`],[`Sernandez et al. 2021 – carico e mobilità precoci nelle fratture di caviglia operate, revisione sistematica e metanalisi (J Orthop Trauma)`,`Sernandez 2021 early weight-bearing range of motion operatively treated ankle fractures meta-analysis`,`PMID 33512860`],[`Willett et al. 2016 – gesso a contatto stretto vs chirurgia nelle fratture instabili di caviglia negli anziani, RCT AIM (JAMA)`,`Willett 2016 close contact casting vs surgery unstable ankle fractures older adults`,`PMID 27727383`],[`Mazzella et al. 2025 – ritorno allo sport negli atleti dopo frattura di caviglia operata, revisione sistematica (J Exp Orthop)`,`Mazzella 2025 return to sport athletes surgical ankle fractures systematic review`,`PMID 41158204`],[`Wright et al. 2023 – criteri di rientro dopo chirurgia di caviglia, scoping review (Foot Ankle Orthop)`,`Wright 2023 return to play decision making after ankle surgery scoping review`,`PMID 37009417`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`],[`Hislop et al. 2017 – programma di controllo del movimento nel rugby scolastico, RCT a cluster (BJSM)`,`Hislop 2017 movement control exercise programme schoolboy rugby`,`PMID 28515056`]]});

S.push({id:`fratture-da-stress`,d:`Caviglia`,t:`Fratture da stress (tibia, metatarsi, navicolare)`,nw:1,
sub:`Sovraccarico osseo: riconoscere le sedi ad alto rischio, gestire il carico e tornare a correre`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`Sono lesioni da sovraccarico dell'osso: tutte nascono da un errore di carico, cioè cicli di carico troppo numerosi o troppo intensi rispetto a quanto l'osso riesce a sopportare (Warden 2021)`,`La sede decide la prognosi: navicolare, corticale anteriore della tibia, V metatarso e collo del femore hanno più complicanze e un rientro più difficile; tibia posteromediale e perone sono le sedi più benigne (Hoenig 2023)`,`Tempi medi di rientro: 127 giorni per il navicolare, 44 per la tibia posteromediale; oltre il 90% degli atleti torna allo sport (Hoenig 2023)`,`Navicolare: diagnosi arrivata in media dopo circa 10 mesi di sintomi; nelle casistiche la chirurgia ha avuto più successo (97,9% vs 78,1%) e meno rifratture (1,3% vs 23,5%) del conservativo (Attia 2021, studi osservazionali)`,`Diapason e ultrasuoni non bastano per la diagnosi: serve l'imaging (Schneiders 2012)`,`Cercare sempre la bassa disponibilità energetica (REDs), anche nei maschi (Mountjoy 2023): nel rugbista che taglia il peso per il ruolo o la categoria è un fattore da indagare`],
inq:[`Continuum: da reazione da stress (osso sofferente, senza linea di frattura) a frattura completa. Il consenso Delphi internazionale (Hoenig 2025, 41 esperti, accordo su 41 di 58 affermazioni) propone un approccio multifattoriale che tiene insieme carico, diagnosi e salute dell'osso`,`Sintomo tipico: dolore localizzato che compare durante la corsa o i salti e cresce settimana dopo settimana, fino a comparire camminando, a riposo o di notte; alla palpazione il dolore è puntiforme sull'osso (pratica clinica)`,`Nel rugby: rischio nei picchi di carico (ripresa estiva, aumento brusco della corsa, cambio di superficie o di scarpe) e con bassa disponibilità energetica. Non sono stati trovati studi di buona qualità sul rugby: i dati vengono da corsa e ambito militare (lacuna)`,`Tibia: distinguere dal dolore mediale da stress tibiale (shin splints), con dolore diffuso lungo il margine mediale, e dalla sindrome compartimentale cronica, con dolore muscolare che cessa a riposo (pratica clinica)`,`Imaging (dai testi): la RX è spesso negativa nelle prime settimane; la RM mostra presto l'edema osseo e permette di graduare la lesione; per il navicolare Attia 2021 raccomanda anche la TC`,`V metatarso: la frattura da stress della zona di Jones (passaggio tra base e diafisi) è ad alto rischio; le fonti di questa scheda non la trattano in modo specifico (lacuna)`,`Recidive frequenti: il trattamento non finisce con la guarigione dell'osso, bisogna correggere ciò che l'ha causata (George 2024, Warden 2021)`],
tab:[{t:`Sedi ad alto e basso rischio`,z:`I`,h:[`Sede`,`Rischio`,`Dati`],r:[[`Navicolare tarsale`,`Alto`,`Rientro più lungo: 127 giorni in media; complicanze frequenti (Hoenig 2023); diagnosi spesso tardiva (Attia 2021)`],[`Corticale anteriore della tibia`,`Alto`,`Complicanze frequenti, rientro difficile (Hoenig 2023)`],[`V metatarso`,`Alto`,`Complicanze frequenti (Hoenig 2023); nessuna fonte dedicata nella scheda`],[`Collo del femore`,`Alto`,`107 giorni in media, complicanze frequenti (Hoenig 2023); vedi la scheda sul dolore inguinale`],[`Tibia posteromediale`,`Basso`,`44 giorni in media, poche complicanze (Hoenig 2023)`],[`Perone`,`Basso`,`56 giorni in media, poche complicanze (Hoenig 2023)`],[`Metatarsi dal II al IV`,`Basso (dai testi)`,`Non riportati separatamente nelle fonti della scheda`]]},{t:`Navicolare: chirurgia o conservativo (Attia 2021)`,z:`T`,h:[`Esito`,`Chirurgia`,`Conservativo`],r:[[`Fratture analizzate (11 studi, 315 fratture)`,`108`,`207`],[`Successo del trattamento`,`97,9% (media)`,`78,1% (media)`],[`Ritorno allo sport`,`97 su 98`,`152 su 207, differenza non significativa`],[`Tempo medio al rientro`,`4,17 mesi`,`4,67 mesi, differenza non significativa`],[`Rifratture`,`1 su 78 (1,3%)`,`20 su 85 (23,5%)`],[`Limite`,`Studi osservazionali eterogenei`,`Nessun RCT`]]}],
red:[`Dolore all'inguine o all'anca da carico nello sportivo: sospetta frattura da stress del collo del femore, stop al carico e imaging urgente.`,`Dolore vago sul dorso del mesopiede, sopra il navicolare, che peggiora con corsa e salti: sede ad alto rischio, imaging (RM o TC) senza aspettare settimane (Attia 2021: diagnosi spesso tardiva).`,`Dolore puntiforme sulla faccia anteriore della tibia a metà gamba, soprattutto in chi salta molto: sede ad alto rischio.`,`Dolore sul bordo esterno del piede alla base del V metatarso: sede ad alto rischio, invio.`,`Dolore a riposo o notturno, gonfiore, impossibilità di caricare.`,`Fratture da stress ricorrenti o multiple, perdita di peso, restrizione alimentare, stanchezza persistente, nelle atlete alterazioni del ciclo: sospetta REDs, invio al medico dello sport (Mountjoy 2023).`,`Dolore osseo senza aumento di carico o con sintomi sistemici (febbre, calo di peso): escludere tumore o infezione.`,`Le red flag cliniche vengono dalla pratica clinica; le fonti indicano le sedi ad alto rischio e la REDs.`],
yel:[`Allenarsi sul dolore per paura di perdere il posto in squadra.`,`Restrizione alimentare o rapporto difficile con il peso: nella REDs conta anche la salute mentale (Mountjoy 2023).`,`Frustrazione per il fermo lungo senza una lesione visibile da fuori.`,`Paura di tornare a correre dopo una recidiva.`],
tst:[[`Palpazione ossea puntiforme`,`Palpare la tibia (margine mediale e faccia anteriore), i metatarsi, il dorso del navicolare e la base del V metatarso.`,`Dolore localizzato su un punto dell'osso: sospetto di frattura da stress, imaging. Dolore diffuso lungo il margine mediale della tibia: più tipico del dolore mediale da stress tibiale (pratica clinica).`],[`Hop test monopodalico`,`Saltelli ripetuti su una gamba sola sul posto.`,`Dolore localizzato: sospetto. Non sono stati trovati dati di accuratezza nelle fonti; non farlo se il sospetto è già alto, soprattutto per il collo del femore o il navicolare (pratica clinica).`],[`Diapason e ultrasuoni terapeutici`,`Diapason vibrante o ultrasuoni sull'osso dolente.`,`Ultrasuoni: sensibilità 64%, specificità 63%; diapason: sensibilità 35-92%, specificità 19-83% (Schneiders 2012). Accuratezza insufficiente: non usarli da soli.`],[`Imaging`,`Su indicazione medica: RX, RM, TC.`,`RX spesso negativa all'inizio; RM per la diagnosi precoce e il grado (dai testi); TC consigliata per il navicolare (Attia 2021).`],[`Screening della disponibilità energetica`,`Domande su alimentazione, peso, energia, sonno, ciclo nelle atlete; valutazione medica con lo strumento IOC REDs CAT2.`,`Il REDs CAT2 serve al medico per riconoscere la REDs e stratificare il rischio (Mountjoy 2023). Al fisioterapista spetta il sospetto e l'invio.`],[`Forza con dinamometro manuale e calf raise`,`Dorsiflessione, inversione, eversione e abduzione d'anca in kg; calf raise monopodalico fino a esaurimento; confronto tra lati.`,`Monitoraggio e criteri per tornare a correre (soglie proposte operative).`]],
ex:[[`Scarico relativo e cammino senza dolore`,`c`,`Cammino quotidiano entro il dolore 0-2/10 (proposta operativa)`,`Basso rischio: si cammina se non fa male, altrimenti stampelle o stivaletto per qualche giorno. Alto rischio: scarico e tempi decisi dal medico.`,`Camminare zoppicando con dolore per non usare le stampelle.`,`Cammino veloce, salite, scale, cammino prolungato.`],[`Condizionamento senza impatto`,`f`,`3-5 sedute/sett., 20-45 min (proposta operativa)`,`Bici, nuoto, corsa in acqua, ergometro a braccia; intervalli per mantenere la condizione aerobica.`,`Scegliere un'attività che fa male sulla sede della frattura.`,`Intervalli ad alta intensità in bici o in acqua.`],[`Forza dell'arto inferiore e del tronco`,`f`,`3-4×6-10 · RPE 6-8 · 2-3/sett. (proposta operativa)`,`Leg press, squat, stacco rumeno, hip thrust, affondi; senza impatto e senza dolore sull'osso durante e il giorno dopo.`,`Inserire salti o corsa nella seduta di forza troppo presto.`,`Carichi più alti, esercizi unilaterali.`],[`Polpaccio e muscoli del piede`,`f`,`3×12-15 → 4×6-10 · RPE 7-8 · 3/sett. (proposta operativa)`,`Calf raise a ginocchio teso e flesso, esercizi dei muscoli intrinseci del piede, tibiale posteriore con elastico.`,`Dolore osseo durante l'esercizio.`,`Calf raise monopodalico con carico.`],[`Saltelli e pliometria progressiva`,`p`,`2-3 sedute/sett. a giorni alterni, pochi contatti crescenti (proposta operativa)`,`Saltelli bipodali sul posto, poi monopodali, poi hop in avanti e laterali, poi salti dal box.`,`Aumentare contatti, altezza e velocità tutti insieme.`,`Drop jump, balzi, appoggi reattivi.`],[`Ritorno alla corsa a intervalli`,`p`,`Corsa e cammino alternati a giorni alterni; si avanza dopo 2 sedute senza dolore (proposta operativa)`,`Prima cresce il volume, poi la velocità e l'intensità (George 2024). Superficie regolare, ritmo facile.`,`Correre il giorno dopo una seduta che ha lasciato dolore osseo; aumentare volume e velocità insieme.`,`Corsa continua, poi ritmi, poi allunghi.`],[`Sprint, cambi di direzione e allenamento di squadra`,`p`,`2-3 sedute/sett., volume crescente (proposta operativa)`,`Accelerazioni, decelerazioni, cambi di direzione, poi allenamento con la squadra e contatto.`,`Rientrare subito con il volume pieno della preparazione.`,`Allenamento completo, poi partita.`]],
fasi:[{n:`Scarico relativo e diagnosi`,w:`basso rischio circa 0-2/3 sett.; alto rischio secondo il medico (indicativo)`,o:`Cammino senza dolore, mantenere la condizione, cercare le cause`,k:`Imaging e sede; analisi del carico recente e della disponibilità energetica (Mountjoy 2023). Navicolare: decisione chirurgica con l'ortopedico; nelle casistiche la chirurgia ha avuto più successo (Attia 2021)`,c:`Cammino senza dolore; per le sedi ad alto rischio via libera del medico`,e:[0,1,2]},{n:`Forza e carico`,w:`circa 2-6 sett. dalla diagnosi nelle sedi a basso rischio (indicativo)`,o:`Forza dell'arto inferiore e del polpaccio senza dolore osseo`,k:`Progressione senza impatti`,c:`Nessun dolore alla palpazione ossea, cammino senza dolore, forza vicina al lato sano; per le sedi ad alto rischio guarigione radiologica (George 2024)`,e:[1,2,3]},{n:`Impatti e ritorno alla corsa`,w:`tibia posteromediale in media circa 6 sett.; navicolare spesso dopo il 3°-4° mese (indicativo, dai tempi medi di Hoenig 2023)`,o:`Tollerare saltelli e corsa`,k:`Programma corsa-cammino, prima il volume e poi l'intensità, guidato dai sintomi (George 2024)`,c:`Corsa continua di 20-30 min senza dolore durante e il giorno dopo (proposta operativa)`,e:[2,3,4,5]},{n:`Velocità e rugby`,w:`dopo la corsa continua senza dolore (indicativo)`,o:`Sprint, cambi di direzione, allenamento di squadra`,k:`Volume di squadra ridotto all'inizio, poi pieno`,c:`Criteri del capitolo del rientro`,e:[3,4,5,6]}],
ev:[[`Gestione del carico guidata dai sintomi, con progressione graduale`,`Centrale`,`Consenso Delphi (Hoenig 2025) e scoping review di evidenza di livello IV (George 2024); nessun RCT`],[`Ricerca e correzione dei fattori favorenti, compresa la bassa disponibilità energetica`,`Centrale`,`Consenso IOC (Mountjoy 2023) e consenso Delphi (Hoenig 2025): opinioni di esperti, non studi di intervento`],[`Fissazione chirurgica nel navicolare dell'atleta`,`Supporto`,`Attia 2021: più successo e meno rifratture rispetto al conservativo, ma solo studi osservazionali eterogenei; decide l'ortopedico`],[`Aumento della cadenza di corsa nelle recidive`,`Supporto`,`Proposta di una revisione narrativa per ridurre il carico sull'osso (Warden 2021), senza dati di efficacia nell'abstract`],[`Diapason o ultrasuoni terapeutici per diagnosticare la frattura`,`Evitare`,`Schneiders 2012: accuratezza insufficiente, serve l'imaging`],[`Tornare a correre con dolore osseo alla palpazione o camminando`,`Evitare`,`George 2024: la scomparsa della dolorabilità ossea e il cammino senza dolore sono prerequisiti per la corsa`]],
rts:{intro:`Non esistono criteri di rientro validati. La scoping review di George 2024 (fratture da stress della tibia, evidenza di livello IV) indica cinque elementi da verificare prima di correre: niente dolore alla palpazione ossea, cammino senza dolore, guarigione radiologica nelle sedi ad alto rischio, test di forza e di carico, fattori favorenti individuati. I tempi medi per sede vengono da Hoenig 2023. Nel rugby il problema non è il contatto ma il volume di corsa e salti: le soglie qui sotto sono proposte operative.`,c:[[`Dolore alla palpazione ossea`,`Pressione puntiforme sulla sede della frattura`,`Assente (George 2024)`,`È il segno clinico più diretto che l'osso tollera di nuovo il carico.`],[`Cammino e vita quotidiana`,`Cammino veloce prolungato, scale`,`30 minuti di cammino veloce senza dolore (proposta operativa)`,`Il cammino senza dolore è un prerequisito per la corsa (George 2024).`],[`Guarigione radiologica nelle sedi ad alto rischio`,`RM o TC su indicazione medica`,`Guarigione documentata e via libera del medico`,`Navicolare, tibia anteriore e V metatarso hanno più complicanze (Hoenig 2023); dopo il conservativo il navicolare si è rifratturato nel 23,5% dei casi (Attia 2021).`],[`Forza`,`Calf raise monopodalico fino a esaurimento; dinamometro manuale per dorsiflessione, inversione, eversione e abduzione d'anca`,`LSI almeno 90% (proposta operativa)`,`I muscoli assorbono parte del carico a ogni appoggio (pratica clinica); i test di forza sono tra i prerequisiti di George 2024.`],[`Tolleranza ai salti`,`Saltelli monopodali ripetuti e hop in avanti`,`Nessun dolore durante e nelle 24 ore successive (proposta operativa)`,`Test di carico prima della corsa (George 2024).`],[`Corsa progressiva`,`Programma corsa-cammino fino a corsa continua, ritmi e sprint`,`Completato senza dolore osseo (proposta operativa)`,`La progressione prima del volume e poi dell'intensità è la linea comune delle raccomandazioni (George 2024).`],[`Fattori favorenti`,`Analisi del carico recente, alimentazione, disponibilità energetica (REDs CAT2 dal medico)`,`Individuati e affrontati`,`Senza correggere la causa la recidiva è frequente (George 2024; Mountjoy 2023).`]],pre:[`Decisione condivisa tra atleta, fisioterapista, medico e allenatori (George 2024)`,`Rientrare con volume di corsa ridotto, evitando di finire la riabilitazione dentro il picco della preparazione (proposta operativa)`,`Navicolare: tempi medi di oltre 4 mesi sia con chirurgia sia con conservativo (Attia 2021)`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`Non sono stati trovati studi sul rugby: i dati vengono soprattutto da corridori e militari. Il V metatarso non ha fonti dedicate in questa scheda (lacuna).`},
sez:[{h:`Prevenzione`,b:[`Progressione graduale del carico, soprattutto dell'intensità, con un monitoraggio costante (Warden 2021, revisione narrativa)`,`Nei giovani carichi brevi, veloci e in più direzioni ed evitare la specializzazione precoce, per costruire uno scheletro robusto (Warden 2021)`,`Dopo fratture ripetute ridurre il carico sull'osso, per esempio aumentando la cadenza di corsa (Warden 2021, proposta senza dati di efficacia nell'abstract)`,`Disponibilità energetica adeguata, con attenzione anche ai carboidrati: il consenso IOC riporta un ruolo crescente della bassa disponibilità di carboidrati (Mountjoy 2023)`,`Nel rugby evitare aumenti bruschi del volume di corsa alla ripresa estiva e nei cambi di ruolo (proposta operativa)`,`Non sono stati trovati studi sulla prevenzione delle fratture da stress nel rugby (lacuna)`]}],
f:[[`Hoenig et al. 2025 – consenso Delphi internazionale sulle lesioni da stress osseo negli atleti (BJSM)`,`Hoenig 2025 international Delphi consensus bone stress injuries athletes`,`PMID 39638438`],[`Hoenig et al. 2023 – ritorno allo sport nelle lesioni da stress osseo ad alto e basso rischio, revisione sistematica e metanalisi (BJSM)`,`Hoenig 2023 return to sport low-risk high-risk bone stress injuries meta-analysis`,`PMID 36720584`],[`Schneiders et al. 2012 – accuratezza dei test clinici per le fratture da stress, revisione sistematica e metanalisi (JOSPT)`,`Schneiders 2012 clinical tests diagnose stress fractures systematic review meta-analysis`,`PMID 22813530`],[`George et al. 2024 – criteri e linee guida per tornare a correre dopo frattura da stress della tibia, scoping review (Sports Med)`,`George 2024 return to running tibial bone stress injury scoping review`,`PMID 39141251`],[`Attia et al. 2021 – ritorno allo sport dopo frattura da stress del navicolare, revisione sistematica e metanalisi (Int Orthop)`,`Attia 2021 navicular stress fracture return to sport meta-analysis`,`PMID 34415421`],[`Mountjoy et al. 2023 – consenso IOC 2023 sul deficit energetico relativo nello sport, REDs (BJSM)`,`Mountjoy 2023 IOC consensus statement Relative Energy Deficiency in Sport REDs`,`PMID 37752011`],[`Warden et al. 2021 – prevenire le lesioni da stress osseo nei corridori con il carico ottimale, revisione narrativa (Curr Osteoporos Rep)`,`Warden 2021 preventing bone stress injuries runners optimal workload`,`PMID 33635519`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`]]});

S.push({id:`peronei-tendinopatia-instabilita`,d:`Caviglia`,t:`Tendinopatia e instabilità dei tendini peronei`,nw:1,
sub:`Dolore laterale dietro al malleolo, lussazione dei peronei e rotture longitudinali: diagnosi, conservativo, chirurgia e rientro`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`I peronei sono i principali evertori del piede e stabilizzatori laterali della caviglia: i loro problemi sono sottovalutati e facili da confondere con una distorsione dei legamenti laterali (Davda 2017)`,`Tre quadri: tendinopatia e tenosinovite, sublussazione e lussazione, rotture longitudinali; spesso associati a instabilità di caviglia, piede cavo e varianti anatomiche (Davda 2017)`,`Lussazione trattata in modo conservativo: con il solo taping recidiva in 18 casi su 30 (60%), con gesso senza carico per almeno 6 settimane successo in 5 casi su 6 (Bakker 2019, studi di livello IV)`,`Chirurgia della lussazione: recidiva sotto l'1,5% a lungo termine; il ritorno allo sport è più frequente con approfondimento della doccia più riparazione del retinacolo che con la sola riparazione del retinacolo (van Dijk 2015)`,`Per le rotture l'ecografia è risultata più sensibile della RM (peroneo breve 93% vs 73%, peroneo lungo 94% vs 60%), con specificità simile; studi tutti ad alto rischio di bias (Ghandour 2025)`,`Non esistono RCT sul trattamento conservativo della tendinopatia dei peronei: il programma di carico qui proposto è una proposta operativa`],
inq:[`Anatomia: peroneo lungo e peroneo breve scorrono nella doccia retromalleolare dietro al perone, trattenuti dal retinacolo superiore dei peronei; il breve si inserisce alla base del V metatarso, il lungo passa sotto il cuboide e arriva alla base del I metatarso (anatomia classica)`,`Meccanismo della lussazione: dorsiflessione forzata del piede mentre i peronei sono contratti, che strappa o scolla il retinacolo superiore (testi e pratica clinica). Nel rugby può succedere in un appoggio bloccato, in un cambio di direzione o nella spinta, ma non sono stati trovati studi specifici sul rugby`,`Spesso diagnosticata come una distorsione laterale banale: il dolore è dietro al malleolo laterale e non davanti, e l'atleta può riferire uno scatto o la sensazione di qualcosa che scivola. Vedi la scheda sulla distorsione laterale di caviglia e instabilità cronica, a cui i problemi dei peronei si associano spesso (Davda 2017)`,`Fattori associati: instabilità laterale cronica, piede cavo con retropiede varo, ventre muscolare del peroneo breve che scende basso nella doccia, presenza di un peroneus quartus (Davda 2017)`,`Imaging: RX, ecografia e RM aiutano la diagnosi (Davda 2017). Per le rotture l'ecografia sembra più sensibile della RM, ma gli studi sono pochi, eterogenei e ad alto rischio di bias: nessuna conclusione sicura sulla superiorità di uno dei due esami (Ghandour 2025)`,`Il consenso internazionale ESSKA-AFAS (van Dijk 2018) ha riunito 16 specialisti di 9 paesi, con revisione sistematica e voto: un'affermazione era accettata con un punteggio medio di almeno 7,5 su 10. È opinione di esperti strutturata (livello V); l'abstract non riporta le singole raccomandazioni, che vanno lette nel testo completo`,`Le raccomandazioni di trattamento, conservativo e chirurgico, si basano su serie di casi e opinione di esperti (Davda 2017)`],
tab:[{t:`Ecografia e RM per le rotture dei peronei (Ghandour 2025)`,z:`V`,h:[`Misura`,`Ecografia`,`RM`],r:[[`Peroneo breve, sensibilità`,`93%`,`73%`],[`Peroneo breve, specificità`,`85%`,`88%`],[`Peroneo lungo, sensibilità`,`94%`,`60%`],[`Peroneo lungo, specificità`,`94%`,`91%`],[`Limite`,`12 studi, tutti ad alto rischio di bias`,`Risultati eterogenei: nessuna conclusione sicura`]]},{t:`Lussazione dei peronei: trattamenti ed esiti`,z:`T`,h:[`Trattamento`,`Esito`,`Fonte`],r:[[`Taping o bendaggio per almeno 3 settimane`,`Recidiva in 18 su 30 (60%); più dolore e instabilità, meno ritorno all'attività precedente`,`Bakker 2019`],[`Gesso per almeno 4 settimane`,`Recidiva in 5 su 13`,`Bakker 2019`],[`Gesso senza carico per almeno 6 settimane`,`Recidiva in 1 su 6, successo in 5 su 6`,`Bakker 2019`],[`Chirurgia (varie tecniche)`,`Recidiva sotto l'1,5% a lungo termine, alta soddisfazione`,`van Dijk 2015`],[`Approfondimento della doccia più riparazione del retinacolo`,`Ritorno allo sport più frequente rispetto alla sola riparazione del retinacolo`,`van Dijk 2015`],[`Limite`,`Tutti studi di livello IV, numeri piccoli`,`Nessun RCT`]]}],
red:[`Dolore osseo sulla base del V metatarso o sul margine posteriore del malleolo laterale, o impossibilità di fare 4 passi dopo il trauma: escludere una frattura (regole di Ottawa).`,`Tendini visibilmente spostati davanti al malleolo che non rientrano nella doccia: invio ortopedico rapido.`,`Piccolo frammento osseo sul margine laterale del perone alla RX: può indicare l'avulsione del retinacolo superiore, cioè una lussazione dei peronei, e non una semplice distorsione.`,`Gonfiore caldo e arrossato lungo i tendini con febbre o malessere: escludere un'infezione.`,`Formicolio o perdita di sensibilità sul dorso o sul bordo laterale del piede: considerare il nervo surale o il peroneo superficiale.`,`Queste red flag vengono dalla pratica clinica e dai testi: le fonti della scheda non le studiano.`],
yel:[`Continuare a giocare con la caviglia che scatta, pensando a una distorsione banale.`,`Paura di caricare su una gamba o di cambiare direzione.`,`Pressione per rientrare a stagione in corso.`],
tst:[[`Palpazione retromalleolare con dorsiflessione ed eversione contro resistenza`,`Dita sulla doccia dietro al malleolo laterale mentre l'atleta porta il piede in alto e in fuori contro la resistenza dell'esaminatore.`,`Dolore lungo il decorso: tendinopatia o rottura. Tendine che scavalca il malleolo o scatto: sublussazione. È l'esame indicato da Davda 2017; non sono stati trovati studi sulla sua accuratezza (lacuna).`],[`Test di compressione dei peronei`,`Pressione del pollice sui tendini nella doccia retromalleolare mentre l'atleta muove il piede in flessione plantare e dorsale ed eversione.`,`Positivo se riproduce dolore o scatto. Test dei testi e della pratica clinica: accuratezza non studiata nelle fonti della scheda.`],[`Circonduzione attiva da prono`,`Atleta prono, ginocchio flesso a 90°: circonduzione attiva della caviglia ed eversione contro resistenza, osservando e palpando la doccia.`,`I tendini che escono dalla doccia indicano un'instabilità; la sublussazione intermittente può sfuggire a una RM statica (pratica clinica).`],[`Tipo di piede e legamenti laterali`,`Osservazione in carico del retropiede; cassetto anteriore e talar tilt come nella scheda sulla distorsione laterale.`,`Piede cavo con retropiede varo e instabilità laterale sono fattori associati da cercare sempre (Davda 2017).`],[`Imaging`,`RX, ecografia anche dinamica, RM su indicazione medica.`,`Ecografia più sensibile della RM per le rotture, specificità simile (Ghandour 2025, qualità bassa). L'ecografia dinamica mostra la sublussazione mentre avviene (pratica clinica).`],[`Forza di eversione con dinamometro manuale`,`Atleta seduto, caviglia in posizione neutra; dinamometro sul bordo laterale del piede vicino al V metatarso; spinta isometrica massimale in eversione per 3-5 s, 3 prove per lato, valore in kg.`,`Monitoraggio e criterio di rientro (soglie proposte nel capitolo del rientro); metodo e soglie sono proposte operative.`]],
ex:[[`Isometrici di eversione`,`i`,`5×30-45 s al 30-50% · RPE 3-5 · quotidiano (proposta operativa)`,`Seduto, bordo esterno del piede contro un oggetto fisso: spingi in fuori senza muovere la caviglia.`,`Dolore oltre 3/10 o sensazione di scatto nella doccia.`,`Isometrici in diverse posizioni di flessione plantare; la dorsiflessione solo quando i tendini sono stabili.`],[`Eversione con elastico, lenta in discesa`,`f`,`3×15 → 4×8-10 · RPE 6-8 · 3/sett. (proposta operativa)`,`Seduto, elastico attorno all'avampiede: porta il piede in fuori in 1 secondo e torna in 3 secondi.`,`Ruotare la gamba o l'anca invece di muovere il piede.`,`Elastico più duro, poi cavigliera o cavo.`],[`Calf raise con spinta sul I metatarso`,`f`,`3×12-15 → 4×6-8 con carico · RPE 7-9 · 2-3/sett. (proposta operativa)`,`Su un gradino, sali spingendo sull'alluce e sulla testa del I metatarso (azione del peroneo lungo) e scendi in 3 secondi.`,`Caviglia che va in supinazione durante la salita, con il peso sul bordo esterno.`,`Monopodalico, poi con manubrio o al multipower.`],[`Equilibrio monopodalico e controllo`,`c`,`3×30-45 s (proposta operativa)`,`Su una gamba, ginocchio morbido; poi lancio e ricezione della palla, occhi chiusi, superfici instabili.`,`Appoggio sul bordo esterno del piede, anca che cede.`,`Perturbazioni del partner, raggiungimenti in più direzioni.`],[`Salti e atterraggi`,`p`,`3×6-10 contatti (proposta operativa)`,`Salti a due piedi, poi su una gamba, avanti e di lato; atterraggio morbido e silenzioso.`,`Atterrare con il piede in inversione o rigido.`,`Salti laterali ripetuti, hop multipli, salti reattivi.`],[`Cambi di direzione e agilità`,`p`,`2-3 sedute/sett. guidate dai sintomi (proposta operativa)`,`Corsa lineare, poi slalom, tagli a 45° e a 90°, side-step.`,`Tagliare con il piede in inversione; saltare i tagli a 90° e passare al gioco.`,`Side-step in situazioni di gioco con avversario.`],[`Progressione al contatto e alla mischia`,`p`,`2-3 sedute/sett. guidate dai sintomi (proposta operativa)`,`Spinta contro scudo e sacco, macchina da mischia, ruck, placcaggio controllato, poi contatto pieno.`,`Spinta in mischia con il piede in dorsiflessione forzata prima di aver recuperato la forza di eversione.`,`Contatto e mischia in situazioni di gioco.`]],
fasi:[{n:`Protezione o calma dei sintomi`,w:`tendinopatia: 0-2/4 sett. (indicativo); lussazione conservativa: gesso senza carico per almeno 6 sett. (Bakker 2019); post-op: decide il chirurgo`,o:`Ridurre il dolore, proteggere il retinacolo o la riparazione`,k:`Tendinopatia: ridurre cambi di direzione, terreni irregolari e inclinati, senza riposo assoluto. Dopo riparazione delle rotture l'immobilizzazione mediana negli studi era di 6 settimane, da 0 a 12 (van Dijk 2016)`,c:`Dolore a riposo assente, cammino senza zoppia`,e:[0]},{n:`Carico progressivo`,w:`circa 2-8 sett. (indicativo)`,o:`Forza di eversione e del polpaccio, controllo in appoggio`,k:`Dopo riparazione delle rotture, il 41% degli studi che lo riportano iniziava la mobilità entro 4 settimane; la tendenza è verso immobilizzazione più breve e mobilità precoce, senza consenso (van Dijk 2016)`,c:`Eversione contro resistenza e calf raise monopodalico senza dolore (proposta operativa)`,e:[0,1,2,3]},{n:`Forza e pliometria`,w:`circa 6-12 sett. (indicativo)`,o:`Forza piena, salti, corsa lineare`,k:`Corsa lineare quando calf raise monopodalico e salti a due piedi sono senza dolore (proposta operativa)`,c:`LSI della forza di eversione ≥80%, salti su una gamba senza dolore né scatto (proposta operativa)`,e:[1,2,3,4]},{n:`Rientro al campo`,w:`tempi non definiti negli studi; dopo chirurgia secondo il chirurgo`,o:`Cambi di direzione, contatto, mischia`,k:`Se c'è instabilità laterale associata, seguire anche il percorso della scheda sulla distorsione laterale`,c:`Criteri del capitolo del rientro`,e:[2,4,5,6]}],
ev:[[`Trattamento conservativo come prima scelta nella tendinopatia: gestione del carico, rinforzo dei peronei, correzione dei fattori associati`,`Centrale`,`Raccomandazioni da serie di casi e opinione di esperti (Davda 2017); nessun RCT sul conservativo (lacuna)`],[`Chirurgia della lussazione con approfondimento della doccia e riparazione del retinacolo`,`Centrale`,`Revisione di 14 studi di livello IV (van Dijk 2015): recidiva sotto l'1,5%, ritorno allo sport più frequente rispetto alla sola riparazione del retinacolo`],[`Gesso senza carico per almeno 6 settimane nella lussazione acuta, se si sceglie il conservativo`,`Supporto`,`Revisione di 6 studi di livello IV (Bakker 2019): successo in 5 casi su 6, numeri molto piccoli`],[`Mobilità precoce dopo riparazione delle rotture`,`Supporto`,`Tendenza negli studi, senza consenso; nessuno studio dedicato alla riabilitazione (van Dijk 2016)`],[`Taping o bendaggio come unico trattamento della lussazione acuta`,`Evitare`,`Recidiva 60%, più dolore e instabilità, meno ritorno all'attività (Bakker 2019, livello IV)`]],
rts:{intro:`Non esistono criteri di rientro validati per i tendini peronei. Gli studi sulla chirurgia della lussazione riportano un ritorno allo sport frequente e rapido, più alto con approfondimento della doccia e riparazione del retinacolo (van Dijk 2015), ma senza criteri e senza dati sul rugby. Le soglie qui sotto sono proposte operative.`,c:[[`Sintomi e stabilità dei tendini`,`Dolore dietro al malleolo e scatto in allenamento; palpazione durante eversione contro resistenza e circonduzione`,`Nessun dolore, nessuno scatto (proposta operativa)`,`Uno scatto residuo indica che il retinacolo non contiene ancora i tendini.`],[`Forza di eversione`,`Dinamometro manuale sul bordo laterale del piede, valore in kg, confronto tra lati`,`LSI ≥90% (proposta operativa)`,`I peronei sono i principali evertori e stabilizzatori laterali (Davda 2017): nei tagli e nei contatti devono frenare l'inversione.`],[`Capacità del polpaccio`,`Calf raise monopodalico fino a esaurimento, contando le ripetizioni`,`LSI ≥90%, senza che la caviglia vada in supinazione (proposta operativa)`,`Sprint, spinta in mischia e salti caricano l'avampiede e i peronei insieme al polpaccio.`],[`Equilibrio e controllo`,`Equilibrio su una gamba a occhi chiusi e raggiungimenti in più direzioni, confronto tra lati`,`Simmetrici, senza compensi (proposta operativa)`,`L'instabilità laterale di caviglia è spesso associata ai problemi dei peronei (Davda 2017).`],[`Salti`,`Hop test su una gamba in avanti e salti laterali ripetuti`,`LSI ≥90%, senza dolore né scatto (proposta operativa)`,`Atterraggi in touche e dopo i contatti avvengono spesso su un piede solo.`],[`Cambi di direzione`,`Side-step e tagli a 90° alla massima velocità`,`Senza dolore né scatto, con fiducia (proposta operativa)`,`Nel taglio il piede a terra carica i peronei in eversione con forza.`],[`Contatto e mischia`,`Spinta in mischia, ruck, placcaggio, poi contatto pieno`,`Tutta la progressione senza sintomi (proposta operativa)`,`La dorsiflessione forzata con i peronei contratti è il meccanismo della lussazione: va provata prima della partita.`]],pre:[`Dopo chirurgia, decisione condivisa con il chirurgo`,`Primo contatto pieno in allenamento, non in partita (proposta operativa)`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`Non sono stati trovati studi sul rugby né criteri di rientro validati: i dati vengono da casistiche miste di livello IV e da un consenso di esperti.`},
sez:[{h:`Prevenzione`,b:[`Non sono stati trovati studi sulla prevenzione della tendinopatia o della lussazione dei peronei (lacuna)`,`Trattare fino in fondo la distorsione laterale e l'instabilità cronica, spesso associate ai problemi dei peronei (Davda 2017); mantenere in stagione equilibrio e forza di eversione (proposta operativa)`,`Misurare a inizio stagione la forza di eversione con il dinamometro, per avere un valore di riferimento in caso di infortunio (proposta operativa)`,`Programmi di riscaldamento come Activate riducono gli infortuni nel rugby giovanile (Hislop 2017), senza dati specifici sui peronei`]}],
f:[[`van Dijk et al. 2018 – consenso internazionale ESSKA-AFAS sulle patologie dei tendini peronei (KSSTA)`,`van Dijk 2018 ESSKA-AFAS international consensus statement peroneal tendon pathologies`,`PMID 29767272`],[`Davda et al. 2017 – patologie dei tendini peronei, rassegna (EFORT Open Rev)`,`Davda 2017 peroneal tendon disorders EFORT Open Reviews`,`PMID 28736620`],[`Bakker et al. 2019 – trattamento conservativo della lussazione dei peronei, revisione sistematica (J Orthop)`,`Bakker non-operative treatment peroneal tendon dislocations systematic review`,`PMID 32082036`],[`van Dijk et al. 2015 – ritorno allo sport ed esiti dopo trattamento della lussazione dei peronei, revisione sistematica (KSSTA)`,`van Dijk 2015 return to sports peroneal tendon dislocation systematic review`,`PMID 26519186`],[`van Dijk et al. 2016 – riabilitazione dopo chirurgia delle rotture dei peronei, revisione sistematica (KSSTA)`,`van Dijk 2016 rehabilitation after surgical treatment peroneal tendon tears ruptures`,`PMID 26803783`],[`Ghandour et al. 2025 – accuratezza di RM ed ecografia per le rotture dei peronei, revisione sistematica e metanalisi (Eur Radiol)`,`Ghandour 2025 diagnostic accuracy MRI ultrasound peroneal tendon tears meta-analysis`,`PMID 40035861`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`],[`Hislop et al. 2017 – programma di controllo del movimento nel rugby scolastico, RCT a cluster (BJSM)`,`Hislop 2017 movement control exercise programme schoolboy rugby`,`PMID 28515056`]]});

S.push({id:`tibiale-posteriore-disfunzione`,d:`Caviglia`,t:`Disfunzione del tibiale posteriore (piede piatto acquisito progressivo)`,nw:1,
sub:`Dolore mediale e arco che cede: classificazione PCFD, plantare ed esercizio, quando inviare all'ortopedico`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`Dal 2020 il consenso propone il nome Progressive Collapsing Foot Deformity (PCFD): una deformità tridimensionale con gradi diversi di valgo del retropiede, abduzione dell'avampiede e varo del mesopiede, non solo una rottura del tendine (Myerson 2020)`,`Riguarda soprattutto adulti sopra i 40 anni, per lo più donne e in sovrappeso (Rhim 2022): nel rugbista giovane è rara, più probabile in ex giocatori o in atleti con piede piatto e sovraccarico mediale`,`Negli stadi iniziali plantare e stretching migliorano dolore e funzione; in un RCT l'aggiunta di rinforzo, soprattutto eccentrico, ha dato il miglioramento maggiore (Kulig 2008), in un altro un programma domiciliare moderato ha aggiunto poco (Houck 2015)`,`Nello stadio II la forza di inversione e adduzione dell'avampiede è ridotta del 20-30% rispetto al lato sano e ai controlli (Houck 2008)`,`L'evidenza sull'esercizio è scarsa: 3 RCT con 93 pazienti in tutto e parametri di prescrizione poco riportati (Ross 2018)`],
inq:[`Il tibiale posteriore inverte il retropiede e sostiene l'arco mediale; il suo tendine passa dietro al malleolo mediale e si inserisce soprattutto sul tubercolo del navicolare (anatomia classica)`,`Visione attuale: la deformità è multifattoriale (displasia ossea, malposizione articolare, squilibrio tra tendini e muscoli). Il ruolo centrale della rottura del tibiale posteriore, che avrebbe innescato una cascata di deformità in ordine fisso, è stato rimesso in discussione (Lalevée 2025)`,`Un piede piatto congenito stabile è in genere asintomatico: è doloroso il piede che cede progressivamente, qualunque sia la sua forma di partenza (Lalevée 2025)`,`Le classificazioni storiche (Johnson e Strom 1989, modificata da Myerson 1997) non sono mai state validate (Myerson 2020). La nuova classificazione distingue cinque componenti, isolate o combinate e senza un ordine cronologico fisso, ciascuna flessibile o rigida (Lalevée 2025)`,`Nel consenso la TC sotto carico è stata accettata come parte della classificazione solo con consenso debole (5 voti su 9), la RM no (3 su 9) (Myerson 2020); la TC sotto carico permette di vedere presto sublussazioni e conflitti articolari (Lalevée 2025)`,`Nelle forme iniziali (tendinopatia, ex stadi I-II) nel cammino si osservano più abduzione dell'avampiede ed eversione del retropiede, con debolezza di anca e caviglia e scarso equilibrio (Rhim 2022)`,`Diagnosi differenziale: lesione del legamento deltoideo, sindrome del tunnel tarsale, frattura da stress del navicolare, artrosi del mesopiede (pratica clinica). Per il dolore plantare al tallone vedi la scheda sulla fascite plantare`],
tab:[{t:`Classificazione PCFD: le cinque componenti`,z:`I`,h:[`Classe`,`Componente`,`Cosa si osserva`],r:[[`A`,`Valgo del retropiede`,`Tallone che devia verso l'esterno visto da dietro`],[`B`,`Abduzione del mesopiede e dell'avampiede`,`Avampiede che punta verso l'esterno: troppe dita visibili da dietro`],[`C`,`Varo dell'avampiede`,`Avampiede supinato rispetto al retropiede quando questo viene corretto`],[`D`,`Sublussazione peritalare`,`Si conferma soprattutto con l'imaging sotto carico`],[`E`,`Valgo tibio-astragalico`,`Inclinazione dell'astragalo nella caviglia`],[`Nota`,`Ogni componente è flessibile o rigida (Lalevée 2025)`,`Le lettere e la descrizione clinica vengono dai testi, non dagli abstract`]]},{t:`Esercizio negli stadi iniziali: cosa dicono gli RCT`,z:`T`,h:[`Studio`,`Confronto`,`Risultato`],r:[[`Kulig 2008 (RCT, 36 adulti, stadi I-II, 12 sett.)`,`Plantare e stretching, con o senza rinforzo concentrico o eccentrico`,`Tutti migliorano; il gruppo con eccentrico migliora di più, quello con solo plantare e stretching di meno`],[`Houck 2015 (RCT, 39 pazienti, stadio II, 12 sett.)`,`Plantare e stretching, con o senza rinforzo domiciliare a intensità moderata`,`Entrambi migliorano; differenze minime, forza isometrica uguale`],[`Ross 2018 (revisione di 3 RCT, 93 pazienti)`,`Rinforzo contro altre forme di conservativo`,`Effetti moderati su dolore e disabilità per l'eccentrico con stretching e plantare; qualità bassa`]]}],
red:[`Dolore mediale acuto dopo un trauma con perdita improvvisa dell'arco: sospetta rottura acuta del tendine o lesione del legamento deltoideo, invio ortopedico.`,`Deformità rigida, non correggibile a mano, o che peggiora rapidamente: invio ortopedico.`,`Piede caldo, gonfio e arrossato con deformità in una persona con diabete o neuropatia: sospetto piede di Charcot, urgenza.`,`Dolore notturno, rigidità mattutina o più articolazioni colpite: escludere una malattia infiammatoria.`,`Formicolio o bruciore sulla pianta del piede: considerare il tunnel tarsale.`,`Queste red flag vengono dalla pratica clinica e dai testi: le fonti della scheda non le studiano.`],
yel:[`Convinzione che il piede piatto sia rotto e che muoversi lo peggiori.`,`Scarsa aderenza a plantare ed esercizio domiciliare: negli RCT i programmi duravano 12 settimane.`,`Pressione a continuare corse lunghe nonostante il dolore.`],
tst:[[`Single heel rise test`,`In piedi su una gamba, con un appoggio leggero per l'equilibrio: salire sulle punte, anche più volte, osservando il tallone da dietro.`,`Normale se il tallone va in varo durante la salita. Incapacità di salire, poche ripetizioni o tallone che resta in valgo indicano una disfunzione del tibiale posteriore. Test dei testi: nessuno studio di accuratezza nelle fonti (lacuna).`],[`Segno delle troppe dita (too many toes)`,`In piedi, visti da dietro: contare le dita visibili all'esterno del tallone e confrontare i lati.`,`Più dita dal lato colpito: abduzione dell'avampiede. Accuratezza non studiata nelle fonti (pratica clinica).`],[`Palpazione e osservazione`,`Gonfiore e dolore lungo il tendine dietro al malleolo mediale fino al navicolare; forma dell'arco e del tallone in carico.`,`Dolore e gonfiore lungo il tendine orientano verso la tendinopatia delle fasi iniziali.`],[`Correggibilità della deformità`,`Da seduto, riportare a mano il tallone in posizione neutra e l'avampiede allineato; osservare se il tallone si corregge nel heel rise.`,`Deformità correggibile: flessibile, terreno del conservativo. Non correggibile: rigida, valutazione ortopedica (pratica clinica; la distinzione flessibile/rigida è parte della classificazione, Lalevée 2025).`],[`Forza di inversione e adduzione con dinamometro manuale`,`Seduto, piede in leggera flessione plantare per limitare il tibiale anteriore; dinamometro sul bordo mediale dell'avampiede; spinta isometrica massimale verso l'interno, 3 prove per lato, valore in kg.`,`Houck 2008, con un trasduttore di forza da laboratorio, ha trovato nello stadio II un deficit del 20-30% (0,70 contro 0,94 N/kg del lato sano). Con il dinamometro manuale metodo e soglie sono proposte operative.`],[`Imaging`,`RX sotto carico, ecografia, RM; TC sotto carico dove disponibile, su indicazione medica.`,`Nel consenso la TC sotto carico è entrata nella classificazione con consenso debole, la RM no (Myerson 2020).`]],
ex:[[`Isometrici di inversione e adduzione`,`i`,`5×30-45 s al 30-50% · RPE 3-5 · quotidiano (proposta operativa)`,`Seduto, bordo interno dell'avampiede contro la gamba del tavolo o un pallone tra i piedi: spingi verso l'interno con la punta leggermente in giù.`,`Alzare la punta del piede (lavora il tibiale anteriore) o ruotare l'anca.`,`Elastico.`],[`Inversione e adduzione con elastico, lenta in discesa`,`f`,`3×15 → 3×10-15 con fase di ritorno in 3 s · RPE 6-8 · 3-5/sett. (proposta operativa)`,`Seduto, elastico attorno all'avampiede tirato verso l'esterno: porta il piede verso l'interno in 1 secondo e torna lentamente in 3 secondi.`,`Muovere l'anca o il ginocchio; fretta nella fase di ritorno, che è quella eccentrica.`,`Elastico più duro, poi esercizi in carico.`],[`Calf raise con pallina tra i talloni`,`f`,`3×12-15 → 4×6-10 con carico · RPE 7-9 · 2-3/sett. (proposta operativa)`,`Pallina stretta tra i talloni, sali sulle punte con il peso verso l'alluce e scendi in 3 secondi: il tallone deve andare in varo.`,`Tallone che cade in valgo o peso sul bordo esterno.`,`Su un gradino, monopodalico, con carico.`],[`Short foot e controllo dell'arco`,`c`,`3×10 da 5-10 s · quotidiano (proposta operativa)`,`In piedi, accorcia il piede sollevando l'arco senza flettere le dita.`,`Dita ad artiglio.`,`Su una gamba, poi in affondo e nel mezzo squat.`],[`Anca ed equilibrio`,`c`,`3×10-15 o 3×30 s · 3/sett. (proposta operativa)`,`Ponte laterale, abduzione d'anca con elastico, equilibrio su una gamba con l'arco attivo.`,`Ginocchio che cade verso l'interno e arco che cede.`,`Superficie instabile, perturbazioni, compiti con la palla.`],[`Stretching del polpaccio`,`m`,`3×30-60 s · quotidiano (proposta operativa)`,`Al muro, prima a ginocchio teso e poi flesso, con l'arco sostenuto o con il plantare.`,`Lasciare che l'arco ceda durante l'allungamento.`,`Su un gradino.`],[`Ritorno alla corsa e ai salti`,`p`,`corsa a intervalli 2-3/sett.; salti 3×6-10 contatti (proposta operativa)`,`Corsa a intervalli con il plantare, poi salti a due piedi e su una gamba, poi cambi di direzione.`,`Aumentare insieme volume e velocità; atterrare con l'arco che collassa.`,`Sprint, tagli, allenamento con la squadra.`]],
fasi:[{n:`Calma dei sintomi e plantare`,w:`0-2/4 sett. (indicativo)`,o:`Ridurre il dolore mediale e scaricare il tendine`,k:`Plantare e stretching sono la base di tutti i gruppi negli RCT (Kulig 2008, Houck 2015). Ridurre corse lunghe e terreni irregolari. Nei casi più dolorosi l'ortopedico può prescrivere un tutore o uno stivaletto (pratica clinica)`,c:`Cammino senza dolore con il plantare`,e:[0,5]},{n:`Rinforzo locale`,w:`circa 2-12 sett. (gli RCT duravano 12 settimane)`,o:`Forza di inversione e adduzione, controllo dell'arco`,k:`Il rinforzo eccentrico aggiunto a plantare e stretching ha dato il miglioramento maggiore in Kulig 2008; in Houck 2015 un programma domiciliare moderato ha aggiunto poco: forse servono intensità e supervisione maggiori (ipotesi, non dimostrata)`,c:`Heel rise monopodalico con il tallone che va in varo, senza dolore (proposta operativa)`,e:[0,1,2,3,5]},{n:`Forza globale e controllo`,w:`circa 8-16 sett. (indicativo)`,o:`Polpaccio, anca, equilibrio`,k:`Debolezza di anca e caviglia e scarso equilibrio sono descritti in queste persone (Rhim 2022)`,c:`LSI della forza di inversione ≥80% al dinamometro (proposta operativa)`,e:[1,2,3,4]},{n:`Ritorno a corsa e sport`,w:`quando i criteri sono raggiunti, spesso dopo 3-4 mesi (indicativo)`,o:`Corsa, salti, cambi di direzione, spinta`,k:`Se la deformità peggiora o diventa rigida nonostante il conservativo: valutazione ortopedica (pratica clinica)`,c:`Criteri del capitolo del rientro`,e:[2,4,6]}],
ev:[[`Plantare con stretching negli stadi iniziali`,`Centrale`,`Base comune degli RCT, con miglioramento in 12 settimane (Kulig 2008, Houck 2015); le prove sui soli plantari sono per lo più osservazionali (Rhim 2022)`],[`Rinforzo progressivo, soprattutto eccentrico, aggiunto a plantare e stretching`,`Supporto`,`Effetti moderati in 3 RCT piccoli e di qualità bassa (Ross 2018); risultati discordanti tra Kulig 2008 e Houck 2015; regime ottimale non noto (Rhim 2022)`],[`Esercizio di anca ed equilibrio`,`Supporto`,`Deficit descritti in studi biomeccanici (Rhim 2022); nessuno studio di efficacia nelle fonti della scheda`],[`Invio ortopedico se la deformità è rigida o progressiva`,`Centrale`,`Pratica clinica; la chirurgia non è trattata dalle fonti della scheda`],[`Solo riposo e terapie passive`,`Evitare`,`Proposta operativa: tutti gli RCT usano plantare ed esercizio attivo`]],
rts:{intro:`Non sono stati trovati studi sul ritorno allo sport nella disfunzione del tibiale posteriore, né su atleti giovani o di contatto: gli studi riguardano adulti per lo più sopra i 40 anni (Rhim 2022). I criteri qui sotto sono proposte operative per tornare a corsa, palestra e campo.`,c:[[`Dolore mediale`,`Dolore e gonfiore dietro al malleolo mediale durante l'allenamento e la mattina dopo, scala 0-10`,`Al massimo 2-3/10 durante, ritorno al livello di base entro 24 ore (proposta operativa)`,`Il dolore del giorno dopo guida il carico nelle tendinopatie (vedi la scheda su dolore, esercizio e monitoraggio).`],[`Single heel rise`,`Salite monopodaliche fino a esaurimento, osservando il tallone`,`Tallone in varo in ogni ripetizione; LSI ≥90% delle ripetizioni (proposta operativa)`,`Valuta insieme forza e funzione del tibiale posteriore; la sua accuratezza non è stata studiata.`],[`Forza di inversione e adduzione`,`Dinamometro manuale con il piede in leggera flessione plantare, valore in kg, confronto tra lati`,`LSI ≥90% (proposta operativa)`,`Nello stadio II il deficit di forza è del 20-30% (Houck 2008): è il primo numero da recuperare.`],[`Forma del piede`,`Osservazione in carico (valgo del tallone, troppe dita) e correggibilità, confrontate con l'inizio`,`Nessun peggioramento, componenti ancora flessibili (proposta operativa)`,`Una deformità che progredisce o diventa rigida richiede la valutazione ortopedica, non il rientro.`],[`Equilibrio e salti`,`Equilibrio su una gamba e hop test, confronto tra lati`,`LSI ≥90%, arco che non collassa all'atterraggio (proposta operativa)`,`Lo scarso equilibrio è descritto in queste persone (Rhim 2022); in campo molti atterraggi avvengono su un piede.`],[`Corsa e cambi di direzione`,`Corsa continua, accelerazioni, sprint, tagli`,`Senza dolore durante e il giorno dopo (proposta operativa)`,`Spinta e tagli caricano l'arco mediale, che il tibiale posteriore sostiene.`],[`Spinta e contatto`,`Spinta contro la macchina da mischia, ruck, poi contatto pieno`,`Senza dolore (proposta operativa)`,`Nella spinta si sta a lungo sugli avampiedi con i talloni sollevati: serve un tibiale posteriore che stabilizzi il retropiede.`]],pre:[`Se la deformità è rigida o progressiva: valutazione ortopedica prima del rientro`,`Plantare anche nelle scarpe da allenamento; con i tacchetti va provato in allenamento, non in partita (proposta operativa)`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`Rilevanza per il rugby limitata: è una condizione tipica di adulti di mezza età. Mancano studi su atleti giovani e criteri di rientro; gli RCT sull'esercizio sono piccoli e con risultati discordanti.`},
sez:[{h:`Prevenzione`,b:[`Non sono stati trovati studi sulla prevenzione (lacuna)`,`Le caratteristiche più frequenti sono età sopra i 40 anni, sesso femminile e sovrappeso (Rhim 2022): negli ex giocatori controllo del peso e mantenimento della forza di polpaccio e piede (proposta operativa)`,`Riconoscere presto il dolore dietro al malleolo mediale: gli studi sul conservativo riguardano gli stadi iniziali, quando il piede è ancora flessibile`,`Nei giocatori con piede piatto misurare a inizio stagione heel rise e forza di inversione con il dinamometro, per avere un valore di riferimento (proposta operativa)`]}],
f:[[`Myerson et al. 2020 – classificazione e nuovo nome: progressive collapsing foot deformity, consenso di esperti (Foot Ankle Int)`,`Myerson 2020 classification nomenclature progressive collapsing foot deformity consensus`,`PMID 32856474`],[`Lalevée et al. 2025 – piede piatto: nuove modalità diagnostiche, rassegna (Orthop Traumatol Surg Res)`,`Lalevee 2025 flatfoot new diagnostic modalities progressive collapsing foot deformity`,`PMID 40935328`],[`Ross et al. 2018 – esercizio nella disfunzione del tibiale posteriore, revisione sistematica di RCT e linee guida (BMJ Open Sport Exerc Med)`,`Ross 2018 exercise posterior tibial tendon dysfunction systematic review randomised clinical trials`,`PMID 30271611`],[`Kulig et al. 2008 – plantari ed esercizio contro resistenza nella disfunzione del tibiale posteriore, RCT (Phys Ther)`,`Kulig 2008 nonsurgical management posterior tibial tendon dysfunction orthoses resistive exercise randomized`,`PMID 19022863`],[`Houck et al. 2015 – plantare con stretching o con stretching e rinforzo nello stadio II, RCT (Foot Ankle Int)`,`Houck 2015 randomized orthosis stretching strengthening stage II tibialis posterior tendon dysfunction`,`PMID 25857939`],[`Houck et al. 2008 – forza del compartimento posteriore profondo nello stadio II, un nuovo test di forza (Foot Ankle Int)`,`Houck 2008 stage II posterior tibial tendon dysfunction deep compartment muscle strength new strength test`,`PMID 18778667`],[`Rhim et al. 2022 – tendinopatia del tibiale posteriore, scoping review (Medicina)`,`Rhim 2022 tibialis posterior tendinopathy scoping review`,`PMID 36557060`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`]]});

S.push({id:`morton-metatarsalgia`,d:`Caviglia`,t:`Neuroma di Morton e metatarsalgia`,nw:1,
sub:`Avampiede che brucia o sassolino nella scarpa: diagnosi clinica, scarpe, infiltrazione ecoguidata e rientro con i tacchetti`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`Il neuroma di Morton è una neuropatia da compressione del nervo digitale plantare comune, di solito nel terzo spazio intermetatarsale e meno spesso nel secondo; dà bruciore o dolore lancinante che si irradia alle dita, o la sensazione di camminare su un sassolino (Matthews 2024)`,`Test di compressione pollice-indice: sensibilità 96%, molto più del click di Mulder (61%) (Mahadevan 2015, 54 piedi già sospettati)`,`Ecografia e RM hanno sensibilità simile (91% e 90%) (Bignotti 2015), ma la RM trova neuromi senza sintomi nel 25% dei piedi di controllo (Owens 2010): l'imaging si legge sempre con la clinica`,`Infiltrazione: aggiungere il cortisone all'anestetico può cambiare poco o nulla su dolore e funzione (certezza bassa); farla sotto guida ecografica probabilmente riduce il dolore più che farla senza (certezza moderata) (Cochrane, Matthews 2024)`,`La metatarsalgia è un sintomo, non una diagnosi: cause primarie, secondarie e iatrogene; la prima linea è conservativa (Besse 2017)`,`Circa il 30% delle persone con neuroma non risponde al trattamento conservativo (Cooper 2023)`],
inq:[`Il neuroma non è un tumore: è un ispessimento con fibrosi del nervo interdigitale (Cooper 2023), una neuropatia degenerativa di origine meccanica (Owens 2010)`,`Metatarsalgia (Besse 2017): cause primarie, secondarie e iatrogene; forme statiche, con dolore in appoggio, e forme propulsive, con dolore nella fase di spinta. Esempi dai testi: II metatarso lungo, insufficienza del I raggio con alluce valgo, retrazione del gastrocnemio, lesione della placca plantare; malattie infiammatorie; esiti di chirurgia dell'avampiede`,`Valutazione della metatarsalgia: esame clinico con RX sotto carico, e se serve ecografia o RM (Besse 2017). L'algoritmo di trattamento cambia se l'alluce è normale o no (Besse 2017): vedi le schede su alluce rigido e su alluce valgo`,`Diagnosi differenziale nel rugbista: frattura da stress dei metatarsi (vedi la scheda sulle fratture da stress), lesione della placca plantare della II metatarso-falangea, borsite intermetatarsale, malattia di Freiberg, radicolopatia (pratica clinica). Il dolore della I metatarso-falangea dopo un'iperestensione fa pensare al turf toe (vedi la scheda)`,`Nel rugby scarpe strette con i tacchetti e carichi ripetuti sull'avampiede (sprint, spinta in mischia) possono favorire i sintomi: è un giudizio clinico, non sono stati trovati studi sul rugby`,`Se il conservativo fallisce si può arrivare alla neurectomia; in un RCT la via plantare e quella dorsale hanno dato soddisfazione e complicanze simili (certezza bassa, Matthews 2024). Dopo la neurectomia un'area di intorpidimento tra le dita è attesa (pratica clinica)`],
tab:[{t:`Test clinici per il neuroma di Morton`,z:`V`,h:[`Test`,`Risultato`,`Fonte`],r:[[`Compressione pollice-indice`,`Sensibilità 96%`,`Mahadevan 2015`],[`Click di Mulder`,`Sensibilità 61%; neuromi più grandi se positivo (10,9 vs 8,5 mm)`,`Mahadevan 2015`],[`Dolorabilità dello spazio intermetatarsale`,`Positiva nel 95% dei piedi operati`,`Owens 2010`],[`Compressione laterale dell'avampiede`,`Sensibilità 41%; positiva nell'88% dei piedi operati`,`Mahadevan 2015; Owens 2010`],[`Percussione plantare`,`Sensibilità 37%; positiva nel 61% dei piedi operati`,`Mahadevan 2015; Owens 2010`],[`Deficit di sensibilità della punta delle dita`,`Sensibilità 26%; positivo nel 67% degli operati, ma simile nei neuromi senza sintomi`,`Mahadevan 2015; Owens 2010`],[`Limite`,`Campioni piccoli di casi già sospettati o operati; specificità non riportata negli abstract`,`Rischio di bias di spettro`]]},{t:`Trattamenti studiati negli RCT (Cochrane, Matthews 2024)`,z:`T`,h:[`Confronto`,`Risultato`,`Certezza`],r:[[`Cortisone più anestetico contro solo anestetico, a 3-6 mesi`,`Poca o nessuna differenza su dolore (6,3 mm in meno su 100, non significativo) e funzione`,`Bassa`],[`Effetti avversi del cortisone`,`Lieve atrofia della pelle 3,9%, ipopigmentazione 3,9%, atrofia del cuscinetto adiposo plantare 2,6%`,`Molto bassa`],[`Infiltrazione ecoguidata contro non guidata, a 6 mesi`,`Dolore 15 mm in meno su 100, funzione migliore`,`Moderata`],[`Neurectomia plantare contro dorsale`,`Soddisfazione e complicanze simili`,`Bassa`],[`Totale`,`6 RCT, 373 pazienti, nessuno a basso rischio di bias in tutti i domini`,`Poche terapie testate in RCT`]]}],
red:[`Dolore osseo puntiforme su un metatarso, con gonfiore dorsale, dopo un aumento del carico di corsa: sospetta frattura da stress, stop alla corsa e imaging.`,`Avampiede caldo, rosso e gonfio, più articolazioni dolenti o rigidità mattutina: sospetta artrite infiammatoria o gotta, invio medico (la metatarsalgia da malattia infiammatoria richiede una strategia specifica, Besse 2017).`,`Intorpidimento esteso a tutto il piede, debolezza o dolore che parte dalla schiena: radicolopatia o neuropatia periferica (per esempio diabetica).`,`Dito che devia progressivamente o si sovrappone al vicino: possibile lesione della placca plantare, valutazione ortopedica.`,`Queste red flag vengono dalla pratica clinica e dai testi; solo la nota sulla malattia infiammatoria è nelle fonti della scheda.`],
yel:[`Rifiuto di cambiare scarpe o tacchetti stretti.`,`Aspettativa che un'infiltrazione risolva tutto senza cambiare scarpe e carichi.`,`Pressione a continuare a giocare con il bruciore.`],
tst:[[`Compressione pollice-indice`,`Pollice e indice stringono lo spazio intermetatarsale tra il dorso e la pianta, uno spazio alla volta.`,`Positivo se riproduce il dolore abituale. Sensibilità 96% rispetto all'ecografia (Mahadevan 2015): il miglior test di screening, ma studiato solo su casi già sospettati.`],[`Click di Mulder`,`Una mano stringe di lato le teste metatarsali, l'altra spinge lo spazio dal basso verso l'alto.`,`Positivo se si sente uno scatto con dolore. Sensibilità 61%; positivo più spesso con neuromi più grandi (Mahadevan 2015).`],[`Dolorabilità dello spazio e compressione laterale`,`Pressione diretta nello spazio intermetatarsale; compressione laterale di tutto l'avampiede.`,`Positive nel 95% e nell'88% dei piedi operati, più spesso che nei controlli (Owens 2010).`],[`Palpazione delle teste metatarsali e cassetto della metatarso-falangea`,`Pressione sulle teste metatarsali e sulle articolazioni; traslazione verso l'alto della falange prossimale tenendo fermo il metatarso.`,`Dolore sulla testa o sull'articolazione, e non nello spazio, orienta verso una metatarsalgia meccanica o una lesione della placca plantare (pratica clinica).`],[`Test di Silfverskiöld`,`Dorsiflessione passiva della caviglia a ginocchio esteso e poi flesso.`,`Limitata solo a ginocchio esteso: retrazione del gastrocnemio, che aumenta il carico sull'avampiede (pratica clinica; l'allungamento chirurgico del gastrocnemio è tra le opzioni citate da Besse 2017).`],[`Imaging`,`Ecografia o RM per il neuroma; RX sotto carico per la metatarsalgia; su indicazione medica.`,`Ecografia e RM con sensibilità simile (91% e 90%), l'ecografia è probabilmente l'esame più conveniente (Bignotti 2015). Neuromi alla RM nel 25% dei controlli senza sintomi (Owens 2010).`]],
ex:[[`Mobilizzazione dell'avampiede`,`m`,`2 sedute/sett. per 3-4 sett. (proposta operativa)`,`Eseguita dal fisioterapista: mobilizzazione delle teste metatarsali tra loro in senso dorso-plantare, apertura degli spazi, mobilizzazione delle metatarso-falangee.`,`Comprimere lo spazio dolente o insistere se il bruciore aumenta.`,`Automobilizzazione ed esercizi attivi del piede.`],[`Stretching del polpaccio`,`m`,`3×30-60 s · quotidiano (proposta operativa)`,`Al muro, prima a ginocchio teso (gastrocnemio) e poi flesso (soleo).`,`Sollevare il tallone o lasciare cedere l'arco.`,`Su un gradino.`],[`Short foot e dita dritte`,`c`,`3×10 da 5 s · quotidiano (proposta operativa)`,`Accorcia il piede sollevando l'arco; poi spingi le dita a terra tenendole dritte, flettendo le metatarso-falangee.`,`Dita ad artiglio, che spingono le teste metatarsali verso il terreno.`,`Su una gamba, poi durante il calf raise.`],[`Calf raise progressivo`,`f`,`3×12-15 → 4×6-10 con carico · RPE 7-9 · 2-3/sett. (proposta operativa)`,`Sali con il peso distribuito su tutte le teste metatarsali, scendi in 3 secondi.`,`Caricare solo sulle teste dolenti o rotolare sul bordo esterno.`,`Monopodalico, con carico, poi veloce.`],[`Forza degli arti inferiori senza impatto`,`f`,`3-4×6-10 · RPE 7-8 · 2-3/sett. (proposta operativa)`,`Squat, stacchi, affondi, hip thrust, bici: mantengono la condizione senza caricare l'avampiede.`,`Esercizi che tengono a lungo sulle punte nelle fasi dolorose.`,`Esercizi in spinta con carico sull'avampiede.`],[`Ritorno a corsa e salti`,`p`,`corsa a intervalli 2-3/sett.; salti 3×6-10 contatti (proposta operativa)`,`Prima con scarpe da corsa ampie, poi con le scarpe da gioco e l'eventuale plantare; salti a due piedi, poi su una gamba.`,`Passare subito ai tacchetti stretti e allo sprint.`,`Accelerazioni e sprint.`],[`Sprint, cambi di direzione e spinta`,`p`,`2-3 sedute/sett. guidate dai sintomi (proposta operativa)`,`Accelerazioni, sprint, side-step, spinta contro la macchina da mischia con le scarpe da gioco.`,`Aumentare insieme volume e velocità.`,`Allenamento completo con la squadra.`]],
fasi:[{n:`Scarico e calzatura`,w:`0-4/6 sett. (indicativo)`,o:`Ridurre la compressione del nervo e il carico sulle teste metatarsali`,k:`Ridurre le attività dolorose, plantari (Cooper 2023), modifiche della calzatura e stretching (Besse 2017); scarpa con avampiede ampio e pad retrocapitale (pratica clinica, tipo e posizione del pad non studiati nelle fonti). Infiltrazione eventuale decisa dal medico, meglio ecoguidata (Matthews 2024)`,c:`Cammino senza dolore con le scarpe di tutti i giorni`,e:[0,1,2,4]},{n:`Carico progressivo`,w:`circa 2-8 sett. (indicativo)`,o:`Forza di polpaccio e piede, tolleranza all'appoggio sull'avampiede`,k:`Monitorare bruciore e formicolio durante e il giorno dopo`,c:`Calf raise monopodalico senza sintomi e senza peggioramento il giorno dopo (proposta operativa)`,e:[1,2,3,4]},{n:`Corsa e salti`,w:`circa 4-10 sett. (indicativo)`,o:`Tollerare corsa e impatti con le scarpe da gioco`,k:`Provare scarpe con tacchetti, plantare o pad in allenamento, non in partita`,c:`Corsa di 20-30 minuti e salti senza bruciore (proposta operativa)`,e:[3,5]},{n:`Rientro al campo`,w:`quando i criteri sono raggiunti; se dopo circa 3 mesi di conservativo ben fatto il dolore resta, rivalutazione medica (proposta operativa)`,o:`Sprint, cambi di direzione, spinta in mischia`,k:`Circa il 30% non risponde al conservativo (Cooper 2023): l'opzione chirurgica si discute con l'ortopedico`,c:`Criteri del capitolo del rientro`,e:[3,5,6]}],
ev:[[`Riduzione delle attività dolorose, calzature adeguate e plantari`,`Centrale`,`Prima linea nelle rassegne (Cooper 2023, Besse 2017); pochi RCT di qualità limitata su plantari e pad (lacuna)`],[`Infiltrazione di cortisone, preferibilmente ecoguidata (decisione medica)`,`Supporto`,`Matthews 2019: meno dolore del controllo (5,3 punti sulla VAS) e più successi rispetto a calzature e pad. Cochrane 2024: rispetto al solo anestetico poca o nessuna differenza (certezza bassa); ecoguidata meglio della non guidata (certezza moderata)`],[`Mobilizzazione e manipolazione dell'avampiede`,`Supporto`,`Un solo RCT: dolore 15,3 punti in meno sulla VAS rispetto al controllo (Matthews 2019)`],[`Stretching del polpaccio ed esercizi del piede`,`Supporto`,`Stretching citato tra le prime linee nella metatarsalgia (Besse 2017); nessuno studio sul rinforzo (proposta operativa)`],[`Neurectomia dopo fallimento del conservativo`,`Supporto`,`Un RCT: via plantare e dorsale con soddisfazione simile (certezza bassa, Matthews 2024)`],[`Sclerosanti, botulino, radiofrequenza o crioneurolisi come prima scelta`,`Evitare`,`Solo serie di casi di qualità limitata (Matthews 2019): non sono una prima linea`]],
rts:{intro:`Non sono stati trovati studi sul ritorno allo sport con neuroma di Morton o metatarsalgia, né sul rugby. Il rientro dipende soprattutto dalla tolleranza della scarpa con i tacchetti e dell'appoggio ripetuto sull'avampiede. Le soglie qui sotto sono proposte operative.`,c:[[`Sintomi nella vita quotidiana`,`Bruciore, formicolio o dolore alle dita nel cammino con le scarpe abituali, scala 0-10`,`Nessun sintomo nelle attività quotidiane (proposta operativa)`,`Se il nervo è irritato già nel cammino, il carico del campo lo peggiora.`],[`Test di compressione`,`Compressione pollice-indice e click di Mulder, confrontati con l'inizio`,`Dolore assente o molto ridotto (proposta operativa)`,`Sono test diagnostici (Mahadevan 2015), non validati per seguire l'andamento: si usano solo come indicazione.`],[`Capacità del polpaccio`,`Calf raise monopodalico fino a esaurimento, contando le ripetizioni`,`LSI ≥90%, senza sintomi all'avampiede (proposta operativa)`,`Sprint e spinta si fanno sull'avampiede e sulle teste metatarsali.`],[`Scarpa da gioco`,`Allenamento completo con i tacchetti e l'eventuale plantare o pad`,`Nessun bruciore durante e nessun peggioramento la mattina dopo (proposta operativa)`,`La scarpa stretta con i tacchetti comprime l'avampiede (giudizio clinico).`],[`Corsa e sprint`,`Corsa continua, accelerazioni, sprint massimale su erba`,`Senza sintomi, durante e il giorno dopo (proposta operativa)`,`Nella fase di spinta il carico sull'avampiede è massimo.`],[`Salti e cambi di direzione`,`Hop test su una gamba e side-step, confronto tra lati`,`LSI ≥90%, senza bruciore (proposta operativa)`,`Atterraggi e tagli caricano l'avampiede in modo brusco.`],[`Spinta in mischia e ruck`,`Spinta contro la macchina da mischia, poi spinta dal vivo`,`Senza sintomi (proposta operativa)`,`Nella spinta si resta a lungo sulle teste metatarsali.`]],pre:[`Dopo un'infiltrazione, chiedere al medico quando riprendere i carichi intensi`,`Dopo neurectomia, tempi decisi dal chirurgo`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`Mancano studi su sportivi e su atleti di contatto; per la metatarsalgia meccanica l'evidenza è soprattutto narrativa e l'efficacia della terapia manuale si basa su un solo RCT.`},
sez:[{h:`Prevenzione`,b:[`Non sono stati trovati studi sulla prevenzione (lacuna)`,`Scarpe da gioco con avampiede adeguato e lacci non troppo stretti sull'avampiede; provare plantari e pad lontano dalle partite (proposta operativa)`,`Aumentare gradualmente il carico di corsa, soprattutto a inizio stagione e sui campi duri (proposta operativa): aiuta anche contro le fratture da stress, che entrano nella diagnosi differenziale`,`Mantenere la mobilità del polpaccio: lo stretching è tra le prime linee nella metatarsalgia (Besse 2017)`]}],
f:[[`Matthews et al. 2024 – trattamenti per il neuroma di Morton, revisione Cochrane (Cochrane Database Syst Rev)`,`Matthews 2024 Cochrane treatments for Morton's neuroma`,`PMID 38334217`],[`Matthews et al. 2019 – efficacia dei trattamenti non chirurgici del neuroma di Morton, revisione sistematica e metanalisi (J Foot Ankle Res)`,`Matthews 2019 non-surgical interventions Morton's neuroma systematic review meta-analysis`,`PMID 30809275`],[`Mahadevan et al. 2015 – accuratezza dei test clinici per il neuroma di Morton rispetto all'ecografia (J Foot Ankle Surg)`,`Mahadevan 2015 diagnostic accuracy clinical tests Morton's neuroma ultrasonography`,`PMID 25432459`],[`Owens et al. 2010 – neuroma di Morton: test clinici e imaging in 76 piedi confrontati con controlli (Foot Ankle Surg)`,`Owens 2010 Morton's neuroma clinical testing imaging 76 feet control group`,`PMID 21783084`],[`Bignotti et al. 2015 – ecografia contro RM per il neuroma di Morton, revisione sistematica e metanalisi (Eur Radiol)`,`Bignotti 2015 ultrasound versus magnetic resonance imaging Morton neuroma meta-analysis`,`PMID 25809742`],[`Besse 2017 – metatarsalgia, rassegna (Orthop Traumatol Surg Res)`,`Besse 2017 metatarsalgia Orthopaedics Traumatology Surgery Research`,`PMID 28109624`],[`Cooper 2023 – patologie dolorose comuni di piede e caviglia, rassegna (JAMA)`,`Cooper 2023 common painful foot and ankle conditions review JAMA`,`PMID 38112812`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`]]});
